public void move(double d, double e, double f) {
   if (this.noPhysics) {
      this.setBoundingBox(this.getBoundingBox().move(d, e, f));
      this.setLocationFromBoundingbox();
   } else {
      this.level.profiler.push("move");
      double g = this.x;
      double h = this.y;
      double i = this.z;
      if (this.inWeb) {
         this.inWeb = false;
         d *= 0.25;
         e *= 0.05F;
         f *= 0.25;
         this.velocityX = 0.0;
         this.velocityY = 0.0;
         this.velocityZ = 0.0;
      }

      double j = d;
      double k = e;
      double l = f;
      boolean bl = this.onGround && this.isSneaking() && this instanceof Player;
      if (bl) {
         double m = 0.05;

         while (d != 0.0 && this.level.doesBoxCollide(this, this.getBoundingBox().move(d, -1.0, 0.0)).isEmpty()) {
            if (d < m && d >= -m) {
               d = 0.0;
            } else if (d > 0.0) {
               d -= m;
            } else {
               d += m;
            }

            j = d;
         }

         for (; f != 0.0 && this.level.doesBoxCollide(this, this.getBoundingBox().move(0.0, -1.0, f)).isEmpty(); l = f) {
            if (f < m && f >= -m) {
               f = 0.0;
            } else if (f > 0.0) {
               f -= m;
            } else {
               f += m;
            }
         }

         for (; d != 0.0 && f != 0.0 && this.level.doesBoxCollide(this, this.getBoundingBox().move(d, -1.0, f)).isEmpty(); l = f) {
            if (d < m && d >= -m) {
               d = 0.0;
            } else if (d > 0.0) {
               d -= m;
            } else {
               d += m;
            }

            j = d;
            if (f < m && f >= -m) {
               f = 0.0;
            } else if (f > 0.0) {
               f -= m;
            } else {
               f += m;
            }
         }
      }

      List<AABB> list = this.level.doesBoxCollide(this, this.getBoundingBox().expandTowards(d, e, f));
      AABB lv = this.getBoundingBox();

      for (AABB lv2 : list) {
         e = lv2.method_589(this.getBoundingBox(), e);
      }

      this.setBoundingBox(this.getBoundingBox().move(0.0, e, 0.0));
      boolean bl2 = this.onGround || k != e && k < 0.0;

      for (AABB lv3 : list) {
         d = lv3.method_583(this.getBoundingBox(), d);
      }

      this.setBoundingBox(this.getBoundingBox().move(d, 0.0, 0.0));

      for (AABB lv3 : list) {
         f = lv3.method_594(this.getBoundingBox(), f);
      }

      this.setBoundingBox(this.getBoundingBox().move(0.0, 0.0, f));
      if (this.maxUpStep > 0.0F && bl2 && (j != d || l != f)) {
         double n = d;
         double o = e;
         double p = f;
         AABB lv4 = this.getBoundingBox();
         this.setBoundingBox(lv);
         d = j;
         e = this.maxUpStep;
         f = l;
         List<AABB> list2 = this.level.doesBoxCollide(this, this.getBoundingBox().expandTowards(d, e, f));
         AABB lv5 = this.getBoundingBox();
         AABB lv6 = lv5.expandTowards(d, 0.0, f);
         double q = e;

         for (AABB lv7 : list2) {
            q = lv7.method_589(lv6, q);
         }

         lv5 = lv5.move(0.0, q, 0.0);
         double r = d;

         for (AABB lv8 : list2) {
            r = lv8.method_583(lv5, r);
         }

         lv5 = lv5.move(r, 0.0, 0.0);
         double s = f;

         for (AABB lv9 : list2) {
            s = lv9.method_594(lv5, s);
         }

         lv5 = lv5.move(0.0, 0.0, s);
         AABB lv10 = this.getBoundingBox();
         double t = e;

         for (AABB lv11 : list2) {
            t = lv11.method_589(lv10, t);
         }

         lv10 = lv10.move(0.0, t, 0.0);
         double u = d;

         for (AABB lv12 : list2) {
            u = lv12.method_583(lv10, u);
         }

         lv10 = lv10.move(u, 0.0, 0.0);
         double v = f;

         for (AABB lv13 : list2) {
            v = lv13.method_594(lv10, v);
         }

         lv10 = lv10.move(0.0, 0.0, v);
         double w = r * r + s * s;
         double x = u * u + v * v;
         if (w > x) {
            d = r;
            f = s;
            e = -q;
            this.setBoundingBox(lv5);
         } else {
            d = u;
            f = v;
            e = -t;
            this.setBoundingBox(lv10);
         }

         for (AABB lv14 : list2) {
            e = lv14.method_589(this.getBoundingBox(), e);
         }

         this.setBoundingBox(this.getBoundingBox().move(0.0, e, 0.0));
         if (n * n + p * p >= d * d + f * f) {
            d = n;
            e = o;
            f = p;
            this.setBoundingBox(lv4);
         }
      }

      this.level.profiler.pop();
      this.level.profiler.push("rest");
      this.setLocationFromBoundingbox();
      this.horizontalCollision = j != d || l != f;
      this.verticalCollision = k != e;
      this.onGround = this.verticalCollision && k < 0.0;
      this.collision = this.horizontalCollision || this.verticalCollision;
      int y = Mth.floor(this.x);
      int z = Mth.floor(this.y - 0.2F);
      int aa = Mth.floor(this.z);
      BlockPos lv15 = new BlockPos(y, z, aa);
      Block lv16 = this.level.getBlockState(lv15).getBlock();
      if (lv16.getMaterial() == Material.AIR) {
         Block lv17 = this.level.getBlockState(lv15.below()).getBlock();
         if (lv17 instanceof FenceBlock || lv17 instanceof WallBlock || lv17 instanceof FenceGateBlock) {
            lv16 = lv17;
            lv15 = lv15.below();
         }
      }

      this.checkFallDamage(e, this.onGround, lv16, lv15);
      if (j != d) {
         this.velocityX = 0.0;
      }

      if (l != f) {
         this.velocityZ = 0.0;
      }

      if (k != e) {
         lv16.updateEntityAfterFallOn(this.level, this);
      }

      if (this.makeStepSound() && !bl && this.vehicle == null) {
         double ab = this.x - g;
         double ac = this.y - h;
         double ad = this.z - i;
         if (lv16 != Blocks.LADDER) {
            ac = 0.0;
         }

         if (lv16 != null && this.onGround) {
            lv16.stepOn(this.level, lv15, this);
         }

         this.walkDist = (float)(this.walkDist + Mth.sqrt(ab * ab + ad * ad) * 0.6);
         this.moveDist = (float)(this.moveDist + Mth.sqrt(ab * ab + ac * ac + ad * ad) * 0.6);
         if (this.moveDist > this.nextStep && lv16.getMaterial() != Material.AIR) {
            this.nextStep = (int)this.moveDist + 1;
            if (this.isInWater()) {
               float ae = Mth.sqrt(this.velocityX * this.velocityX * 0.2F + this.velocityY * this.velocityY + this.velocityZ * this.velocityZ * 0.2F)
                  * 0.35F;
               if (ae > 1.0F) {
                  ae = 1.0F;
               }

               this.playSound(this.getSwimSound(), ae, 1.0F + (this.random.nextFloat() - this.random.nextFloat()) * 0.4F);
            }

            this.playStepSound(lv15, lv16);
         }
      }

      try {
         this.checkInsideBlocks();
      } catch (Throwable throwable) {
         CrashReport lv18 = CrashReport.forThrowable(throwable, "Checking entity block collision");
         CrashReportCategory lv19 = lv18.addCategory("Entity being checked for collision");
         this.fillCrashReportCategory(lv19);
         throw new ReportedException(lv18);
      }

      boolean bl3 = this.isInRain();
      if (this.level.containsFireBlock(this.getBoundingBox().deflate(0.001, 0.001, 0.001))) {
         this.burn(1);
         if (!bl3) {
            this.remainingFireTicks++;
            if (this.remainingFireTicks == 0) {
               this.setSecondsOnFire(8);
            }
         }
      } else if (this.remainingFireTicks <= 0) {
         this.remainingFireTicks = -this.fireResistance;
      }

      if (bl3 && this.remainingFireTicks > 0) {
         this.playSound("random.fizz", 0.7F, 1.6F + (this.random.nextFloat() - this.random.nextFloat()) * 0.4F);
         this.remainingFireTicks = -this.fireResistance;
      }

      this.level.profiler.pop();
   }
}

push.source:
public void push(Entity arg) {
   if (arg.rider != this && arg.vehicle != this) {
      if (!arg.noPhysics && !this.noPhysics) {
         double d = arg.x - this.x;
         double e = arg.z - this.z;
         double f = Mth.absMax(d, e);
         if (f >= 0.01F) {
            f = Mth.sqrt(f);
            d /= f;
            e /= f;
            double g = 1.0 / f;
            if (g > 1.0) {
               g = 1.0;
            }

            d *= g;
            e *= g;
            d *= 0.05F;
            e *= 0.05F;
            d *= 1.0F - this.pushthrough;
            e *= 1.0F - this.pushthrough;
            if (this.rider == null) {
               this.push(-d, 0.0, -e);
            }

            if (arg.rider == null) {
               arg.push(d, 0.0, e);
            }
         }
      }
   }
}

public void push(double d, double e, double f) {
   this.velocityX += d;
   this.velocityY += e;
   this.velocityZ += f;
   this.hasImpulse = true;
}

rideTick.source:
public void rideTick() {
   if (this.vehicle.removed) {
      this.vehicle = null;
   } else {
      this.velocityX = 0.0;
      this.velocityY = 0.0;
      this.velocityZ = 0.0;
      this.tick();
      if (this.vehicle != null) {
         this.vehicle.positionRider();
         this.vehicleYaw = this.vehicleYaw + (this.vehicle.yRot - this.vehicle.yRotO);
         this.vehiclePitch = this.vehiclePitch + (this.vehicle.xRot - this.vehicle.xRotO);

         while (this.vehicleYaw >= 180.0) {
            this.vehicleYaw -= 360.0;
         }

         while (this.vehicleYaw < -180.0) {
            this.vehicleYaw += 360.0;
         }

         while (this.vehiclePitch >= 180.0) {
            this.vehiclePitch -= 360.0;
         }

         while (this.vehiclePitch < -180.0) {
            this.vehiclePitch += 360.0;
         }

         double d = this.vehicleYaw * 0.5;
         double e = this.vehiclePitch * 0.5;
         float f = 10.0F;
         if (d > f) {
            d = f;
         }

         if (d < -f) {
            d = -f;
         }

         if (e > f) {
            e = f;
         }

         if (e < -f) {
            e = -f;
         }

         this.vehicleYaw -= d;
         this.vehiclePitch -= e;
      }
   }
}

travel.source:
public void travel(float f, float g) {
   if (this.isEffectiveAi()) {
      if (!this.isInWater() || this instanceof Player && ((Player)this).abilities.flying) {
         if (!this.isInLava() || this instanceof Player && ((Player)this).abilities.flying) {
            float k = 0.91F;
            if (this.onGround) {
               k = this.level.getBlockState(new BlockPos(Mth.floor(this.x), Mth.floor(this.getBoundingBox().minY) - 1, Mth.floor(this.z))).getBlock().friction
                  * 0.91F;
            }

            float l = 0.16277136F / (k * k * k);
            float h;
            if (this.onGround) {
               h = this.getSpeed() * l;
            } else {
               h = this.flyingSpeed;
            }

            this.moveRelative(f, g, h);
            k = 0.91F;
            if (this.onGround) {
               k = this.level.getBlockState(new BlockPos(Mth.floor(this.x), Mth.floor(this.getBoundingBox().minY) - 1, Mth.floor(this.z))).getBlock().friction
                  * 0.91F;
            }

            if (this.onLadder()) {
               float i = 0.15F;
               this.velocityX = Mth.clamp(this.velocityX, -i, i);
               this.velocityZ = Mth.clamp(this.velocityZ, -i, i);
               this.fallDistance = 0.0F;
               if (this.velocityY < -0.15) {
                  this.velocityY = -0.15;
               }

               boolean bl = this.isSneaking() && this instanceof Player;
               if (bl && this.velocityY < 0.0) {
                  this.velocityY = 0.0;
               }
            }

            this.move(this.velocityX, this.velocityY, this.velocityZ);
            if (this.horizontalCollision && this.onLadder()) {
               this.velocityY = 0.2;
            }

            if (this.level.isClientSide
               && (
                  !this.level.blockExists(new BlockPos((int)this.x, 0, (int)this.z))
                     || !this.level.getChunkAt(new BlockPos((int)this.x, 0, (int)this.z)).isLoaded()
               )) {
               if (this.y > 0.0) {
                  this.velocityY = -0.1;
               } else {
                  this.velocityY = 0.0;
               }
            } else {
               this.velocityY -= 0.08;
            }

            this.velocityY *= 0.98F;
            this.velocityX *= k;
            this.velocityZ *= k;
         } else {
            double d = this.y;
            this.moveRelative(f, g, 0.02F);
            this.move(this.velocityX, this.velocityY, this.velocityZ);
            this.velocityX *= 0.5;
            this.velocityY *= 0.5;
            this.velocityZ *= 0.5;
            this.velocityY -= 0.02;
            if (this.horizontalCollision && this.isFree(this.velocityX, this.velocityY + 0.6F - this.y + d, this.velocityZ)) {
               this.velocityY = 0.3F;
            }
         }
      } else {
         double d = this.y;
         float h = 0.8F;
         float i = 0.02F;
         float j = EnchantmentHelper.getDepthStrider(this);
         if (j > 3.0F) {
            j = 3.0F;
         }

         if (!this.onGround) {
            j *= 0.5F;
         }

         if (j > 0.0F) {
            h += (0.54600006F - h) * j / 3.0F;
            i += (this.getSpeed() * 1.0F - i) * j / 3.0F;
         }

         this.moveRelative(f, g, i);
         this.move(this.velocityX, this.velocityY, this.velocityZ);
         this.velocityX *= h;
         this.velocityY *= 0.8F;
         this.velocityZ *= h;
         this.velocityY -= 0.02;
         if (this.horizontalCollision && this.isFree(this.velocityX, this.velocityY + 0.6F - this.y + d, this.velocityZ)) {
            this.velocityY = 0.3F;
         }
      }
   }

   this.animationSpeedOld = this.animationSpeed;
   double d = this.x - this.xo;
   double e = this.z - this.zo;
   float j = Mth.sqrt(d * d + e * e) * 4.0F;
   if (j > 1.0F) {
      j = 1.0F;
   }

   this.animationSpeed = this.animationSpeed + (j - this.animationSpeed) * 0.4F;
   this.animationPosition = this.animationPosition + this.animationSpeed;
}

causeFallDamage.source:
public void causeFallDamage(float f, float g) {
   super.causeFallDamage(f, g);
   MobEffectInstance lv = this.getEffect(MobEffect.JUMP_BOOST);
   float h = lv != null ? lv.getAmplifier() + 1 : 0.0F;
   int i = Mth.ceil((f - 3.0F - h) * g);
   if (i > 0) {
      this.playSound(this.getFallDamageSound(i), 1.0F, 1.0F);
      this.hurt(DamageSource.FALL, i);
      int j = Mth.floor(this.x);
      int k = Mth.floor(this.y - 0.2F);
      int l = Mth.floor(this.z);
      Block lv2 = this.level.getBlockState(new BlockPos(j, k, l)).getBlock();
      if (lv2.getMaterial() != Material.AIR) {
         Block.Sound lv3 = lv2.sound;
         this.playSound(lv3.getStepSound(), lv3.getVolume() * 0.5F, lv3.getPitch() * 0.75F);
      }
   }
}

travel.source:
public void travel(float f, float g) {
   double d = this.x;
   double e = this.y;
   double h = this.z;
   if (this.abilities.flying && this.vehicle == null) {
      double i = this.velocityY;
      float j = this.flyingSpeed;
      this.flyingSpeed = this.abilities.getFlyingSpeed() * (this.isSprinting() ? 2 : 1);
      super.travel(f, g);
      this.velocityY = i * 0.6;
      this.flyingSpeed = j;
   } else {
      super.travel(f, g);
   }

   this.checkMovementStatistics(this.x - d, this.y - e, this.z - h);
}

aiStep.source:
public void aiStep() {
   if (this.jumpTriggerTime > 0) {
      this.jumpTriggerTime--;
   }

   if (this.level.getGlobalDifficulty() == Difficulty.PEACEFUL && this.level.getGameRules().getBoolean("naturalRegeneration")) {
      if (this.getHealth() < this.getMaxHealth() && this.tickCount % 20 == 0) {
         this.heal(1.0F);
      }

      if (this.foodData.needsFood() && this.tickCount % 10 == 0) {
         this.foodData.setFoodLevel(this.foodData.getFoodLevel() + 1);
      }
   }

   this.inventory.tick();
   this.oBob = this.bob;
   super.aiStep();
   AttributeInstance lv = this.getAttribute(SharedMonsterAttributes.MOVEMENT_SPEED);
   if (!this.level.isClientSide) {
      lv.setBaseValue(this.abilities.getWalkingSpeed());
   }

   this.flyingSpeed = this.defaultFlySpeed;
   if (this.isSprinting()) {
      this.flyingSpeed = (float)(this.flyingSpeed + this.defaultFlySpeed * 0.3);
   }

   this.setSpeed((float)lv.getValue());
   float f = Mth.sqrt(this.velocityX * this.velocityX + this.velocityZ * this.velocityZ);
   float g = (float)(Math.atan(-this.velocityY * 0.2F) * 15.0);
   if (f > 0.1F) {
      f = 0.1F;
   }

   if (!this.onGround || this.getHealth() <= 0.0F) {
      f = 0.0F;
   }

   if (this.onGround || this.getHealth() <= 0.0F) {
      g = 0.0F;
   }

   this.bob = this.bob + (f - this.bob) * 0.4F;
   this.field_6753 = this.field_6753 + (g - this.field_6753) * 0.8F;
   if (this.getHealth() > 0.0F && !this.isSpectator()) {
      AABB lv2 = null;
      if (this.vehicle != null && !this.vehicle.removed) {
         lv2 = this.getBoundingBox().minmax(this.vehicle.getBoundingBox()).inflate(1.0, 0.0, 1.0);
      } else {
         lv2 = this.getBoundingBox().inflate(1.0, 0.5, 1.0);
      }

      List<Entity> list = this.level.getEntitiesIn(this, lv2);

      for (int i = 0; i < list.size(); i++) {
         Entity lv3 = list.get(i);
         if (!lv3.removed) {
            this.touch(lv3);
         }
      }
   }
}

rideTick.source:
public void rideTick() {
   if (!this.level.isClientSide && this.isSneaking()) {
      this.startRiding(null);
      this.setSneaking(false);
   } else {
      double d = this.x;
      double e = this.y;
      double f = this.z;
      float g = this.yRot;
      float h = this.xRot;
      super.rideTick();
      this.oBob = this.bob;
      this.bob = 0.0F;
      this.checkRidingStatistiscs(this.x - d, this.y - e, this.z - f);
      if (this.vehicle instanceof Pig) {
         this.xRot = h;
         this.yRot = g;
         this.yBodyRot = ((Pig)this.vehicle).yBodyRot;
      }
   }
}

aiStep.source:
public void aiStep() {
   if (this.sprintTime > 0) {
      this.sprintTime--;
      if (this.sprintTime == 0) {
         this.setSprinting(false);
      }
   }

   if (this.sprintTriggerTime > 0) {
      this.sprintTriggerTime--;
   }

   this.oPortalTime = this.portalTime;
   if (this.isInsidePortal) {
      if (this.minecraft.screen != null && !this.minecraft.screen.isPauseScreen()) {
         this.minecraft.setScreen(null);
      }

      if (this.portalTime == 0.0F) {
         this.minecraft.getSoundManager().play(SimpleSoundInstance.forUI(new ResourceLocation("portal.trigger"), this.random.nextFloat() * 0.4F + 0.8F));
      }

      this.portalTime += 0.0125F;
      if (this.portalTime >= 1.0F) {
         this.portalTime = 1.0F;
      }

      this.isInsidePortal = false;
   } else if (this.hasEffect(MobEffect.NAUSEA) && this.getEffect(MobEffect.NAUSEA).getDuration() > 60) {
      this.portalTime += 0.006666667F;
      if (this.portalTime > 1.0F) {
         this.portalTime = 1.0F;
      }
   } else {
      if (this.portalTime > 0.0F) {
         this.portalTime -= 0.05F;
      }

      if (this.portalTime < 0.0F) {
         this.portalTime = 0.0F;
      }
   }

   if (this.changingDimensionDelay > 0) {
      this.changingDimensionDelay--;
   }

   boolean bl = this.input.jumping;
   boolean bl2 = this.input.sneakKeyDown;
   float f = 0.8F;
   boolean bl3 = this.input.forwardImpulse >= f;
   this.input.tick();
   if (this.isUsingItem() && !this.isPassenger()) {
      this.input.leftImpulse *= 0.2F;
      this.input.forwardImpulse *= 0.2F;
      this.sprintTriggerTime = 0;
   }

   this.checkInBlock(this.x - this.width * 0.35, this.getBoundingBox().minY + 0.5, this.z + this.width * 0.35);
   this.checkInBlock(this.x - this.width * 0.35, this.getBoundingBox().minY + 0.5, this.z - this.width * 0.35);
   this.checkInBlock(this.x + this.width * 0.35, this.getBoundingBox().minY + 0.5, this.z - this.width * 0.35);
   this.checkInBlock(this.x + this.width * 0.35, this.getBoundingBox().minY + 0.5, this.z + this.width * 0.35);
   boolean bl4 = this.getFoodData().getFoodLevel() > 6.0F || this.abilities.mayfly;
   if (this.onGround
      && !bl2
      && !bl3
      && this.input.forwardImpulse >= f
      && !this.isSprinting()
      && bl4
      && !this.isUsingItem()
      && !this.hasEffect(MobEffect.BLINDNESS)) {
      if (this.sprintTriggerTime <= 0 && !this.minecraft.options.keySprint.isDown()) {
         this.sprintTriggerTime = 7;
      } else {
         this.setSprinting(true);
      }
   }

   if (!this.isSprinting()
      && this.input.forwardImpulse >= f
      && bl4
      && !this.isUsingItem()
      && !this.hasEffect(MobEffect.BLINDNESS)
      && this.minecraft.options.keySprint.isDown()) {
      this.setSprinting(true);
   }

   if (this.isSprinting() && (this.input.forwardImpulse < f || this.horizontalCollision || !bl4)) {
      this.setSprinting(false);
   }

   if (this.abilities.mayfly) {
      if (this.minecraft.gameMode.isAlwaysFlying()) {
         if (!this.abilities.flying) {
            this.abilities.flying = true;
            this.onUpdateAbilities();
         }
      } else if (!bl && this.input.jumping) {
         if (this.jumpTriggerTime == 0) {
