tick.source:
public void tick() {
   if (this.getHurtTime() > 0) {
      this.setHurtTime(this.getHurtTime() - 1);
   }

   if (this.getDamage() > 0.0F) {
      this.setDamage(this.getDamage() - 1.0F);
   }

   if (this.y < -64.0) {
      this.outOfWorld();
   }

   if (!this.level.isClientSide && this.level instanceof ServerLevel) {
      this.level.profiler.push("portal");
      MinecraftServer minecraftServer = this.level.getServer();
      int i = this.getPortalWaitTime();
      if (this.isInsidePortal) {
         if (minecraftServer.isNetherEnabled()) {
            if (!this.isPassenger() && this.portalTime++ >= i) {
               this.portalTime = i;
               this.changingDimensionDelay = this.getDimensionChangingDelay();
               int j;
               if (this.level.dimension.getType().getId() == -1) {
                  j = 0;
               } else {
                  j = -1;
               }

               this.changeDimension(j);
            }

            this.isInsidePortal = false;
         }
      } else {
         if (this.portalTime > 0) {
            this.portalTime -= 4;
         }

         if (this.portalTime < 0) {
            this.portalTime = 0;
         }
      }

      if (this.changingDimensionDelay > 0) {
         this.changingDimensionDelay--;
      }

      this.level.profiler.pop();
   }

   if (this.level.isClientSide) {
      if (this.lSteps > 0) {
         double d = this.x + (this.lx - this.x) / this.lSteps;
         double e = this.y + (this.ly - this.y) / this.lSteps;
         double f = this.z + (this.lz - this.z) / this.lSteps;
         double g = Mth.wrapDegrees(this.lyr - this.yRot);
         this.yRot = (float)(this.yRot + g / this.lSteps);
         this.xRot = (float)(this.xRot + (this.lxr - this.xRot) / this.lSteps);
         this.lSteps--;
         this.setPos(d, e, f);
         this.setRot(this.yRot, this.xRot);
      } else {
         this.setPos(this.x, this.y, this.z);
         this.setRot(this.yRot, this.xRot);
      }
   } else {
      this.xo = this.x;
      this.yo = this.y;
      this.zo = this.z;
      this.velocityY -= 0.04F;
      int k = Mth.floor(this.x);
      int i = Mth.floor(this.y);
      int j = Mth.floor(this.z);
      if (BaseRailBlock.isRail(this.level, new BlockPos(k, i - 1, j))) {
         i--;
      }

      BlockPos lv = new BlockPos(k, i, j);
      BlockState lv2 = this.level.getBlockState(lv);
      if (BaseRailBlock.isRail(lv2)) {
         this.moveAlongTrack(lv, lv2);
         if (lv2.getBlock() == Blocks.ACTIVATOR_RAIL) {
            this.activateMinecart(k, i, j, lv2.get(PoweredRailBlock.POWERED));
         }
      } else {
         this.comeOffTrack();
      }

      this.checkInsideBlocks();
      this.xRot = 0.0F;
      double h = this.xo - this.x;
      double l = this.zo - this.z;
      if (h * h + l * l > 0.001) {
         this.yRot = (float)(Mth.atan2(l, h) * 180.0 / Math.PI);
         if (this.flipped) {
            this.yRot += 180.0F;
         }
      }

      double m = Mth.wrapDegrees(this.yRot - this.yRotO);
      if (m < -170.0 || m >= 170.0) {
         this.yRot += 180.0F;
         this.flipped = !this.flipped;
      }

      this.setRot(this.yRot, this.xRot);

      for (Entity lv3 : this.level.getEntitiesIn(this, this.getBoundingBox().inflate(0.2F, 0.0, 0.2F))) {
         if (!this.hasPassenger(lv3) && lv3.isPushable() && lv3 instanceof AbstractMinecart) {
            lv3.push(this);
         }
      }

      this.updateWaterState();
   }
}

travel.source:
public void travel(float f, float g) {
   if (this.isVehicle() && this.canBeControlledByRider() && this.isSaddled()) {
      LivingEntity lv = (LivingEntity)this.getControllingPassenger();
      this.yRotO = this.yRot = lv.yRot;
      this.xRot = lv.xRot * 0.5F;
      this.setRot(this.yRot, this.xRot);
      this.yHeadRot = this.yBodyRot = this.yRot;
      f = lv.xxa * 0.5F;
      g = lv.zza;
      if (g <= 0.0F) {
         g *= 0.25F;
         this.gallopSoundCounter = 0;
      }

      if (this.onGround && this.playerJumpPendingScale == 0.0F && this.isStanding() && !this.allowStandSliding) {
         f = 0.0F;
         g = 0.0F;
      }

      if (this.playerJumpPendingScale > 0.0F && !this.isJumping() && this.onGround) {
         this.velocityY = this.getCustomJump() * this.playerJumpPendingScale;
         if (this.hasEffect(MobEffects.JUMP)) {
            this.velocityY = this.velocityY + (this.getEffect(MobEffects.JUMP).getAmplifier() + 1) * 0.1F;
         }

         this.setIsJumping(true);
         this.hasImpulse = true;
         if (g > 0.0F) {
            float h = Mth.sin(this.yRot * (float) (Math.PI / 180.0));
            float i = Mth.cos(this.yRot * (float) (Math.PI / 180.0));
            this.velocityX = this.velocityX + -0.4F * h * this.playerJumpPendingScale;
            this.velocityZ = this.velocityZ + 0.4F * i * this.playerJumpPendingScale;
            this.playSound(SoundEvents.HORSE_JUMP, 0.4F, 1.0F);
         }

         this.playerJumpPendingScale = 0.0F;
      }

      this.flyingSpeed = this.getSpeed() * 0.1F;
      if (this.isControlledByLocalInstance()) {
         this.setSpeed((float)this.getAttribute(SharedMonsterAttributes.MOVEMENT_SPEED).getValue());
         super.travel(f, g);
      } else if (lv instanceof Player) {
         this.velocityX = 0.0;
         this.velocityY = 0.0;
         this.velocityZ = 0.0;
      }

      if (this.onGround) {
         this.playerJumpPendingScale = 0.0F;
         this.setIsJumping(false);
      }

      this.animationSpeedOld = this.animationSpeed;
      double d = this.x - this.xo;
      double e = this.z - this.zo;
      float j = Mth.sqrt(d * d + e * e) * 4.0F;
      if (j > 1.0F) {
         j = 1.0F;
      }

      this.animationSpeed = this.animationSpeed + (j - this.animationSpeed) * 0.4F;
      this.animationPosition = this.animationPosition + this.animationSpeed;
   } else {
      this.flyingSpeed = 0.02F;
      super.travel(f, g);
   }
}

