public static final void rotateTowardsMovement(Entity arg, float f) {
   double d = arg.velocityX;
   double e = arg.velocityY;
   double g = arg.velocityZ;
   float h = Mth.sqrt(d * d + g * g);
   arg.yRot = (float)(Mth.atan2(g, d) * 180.0F / (float)Math.PI) + 90.0F;
   arg.xRot = (float)(Mth.atan2(h, e) * 180.0F / (float)Math.PI) - 90.0F;

   while (arg.xRot - arg.xRotO < -180.0F) {
      arg.xRotO -= 360.0F;
   }

   while (arg.xRot - arg.xRotO >= 180.0F) {
      arg.xRotO += 360.0F;
   }

   while (arg.yRot - arg.yRotO < -180.0F) {
      arg.yRotO -= 360.0F;
   }

   while (arg.yRot - arg.yRotO >= 180.0F) {
      arg.yRotO += 360.0F;
   }

   arg.xRot = arg.xRotO + (arg.xRot - arg.xRotO) * f;
   arg.yRot = arg.yRotO + (arg.yRot - arg.yRotO) * f;
}

