   arg.xRot = (float)(Mth.atan2(h, e) * 180.0F / (float)Math.PI) - 90.0F;

   while (arg.xRot - arg.xRotO < -180.0F) {
      arg.xRotO -= 360.0F;
   }

   while (arg.xRot - arg.xRotO >= 180.0F) {
      arg.xRotO += 360.0F;
   }

   while (arg.yRot - arg.yRotO < -180.0F) {
      arg.yRotO -= 360.0F;
   }

   while (arg.yRot - arg.yRotO >= 180.0F) {
