public void push(Entity arg) {
   if (!this.isPassengerOfSameVehicle(arg)) {
      if (!arg.noPhysics && !this.noPhysics) {
         double d = arg.x - this.x;
         double e = arg.z - this.z;
         double f = Mth.absMax(d, e);
         if (f >= 0.01F) {
            f = Mth.sqrt(f);
            d /= f;
            e /= f;
            double g = 1.0 / f;
            if (g > 1.0) {
               g = 1.0;
            }

            d *= g;
            e *= g;
            d *= 0.05F;
            e *= 0.05F;
            d *= 1.0F - this.pushthrough;
            e *= 1.0F - this.pushthrough;
            if (!this.isVehicle()) {
               this.push(-d, 0.0, -e);
            }

            if (!arg.isVehicle()) {
               arg.push(d, 0.0, e);
            }
         }
      }
   }
}

public void push(double d, double e, double f) {
   this.velocityX += d;
   this.velocityY += e;
   this.velocityZ += f;
   this.hasImpulse = true;
}

