   }

   boolean bl4 = false;
   if (this.autoJumpTime > 0) {
      this.autoJumpTime--;
      bl4 = true;
      this.input.jumping = true;
   }

   AABB lv = this.getBoundingBox();
   this.checkInBlock(this.x - this.width * 0.35, lv.minY + 0.5, this.z + this.width * 0.35);
   this.checkInBlock(this.x - this.width * 0.35, lv.minY + 0.5, this.z - this.width * 0.35);
