   this.checkInBlock(this.x + this.width * 0.35, lv.minY + 0.5, this.z + this.width * 0.35);
   boolean bl5 = this.getFoodData().getFoodLevel() > 6.0F || this.abilities.mayfly;
   if (this.onGround
      && !bl2
