         this.connection.send(new ServerboundPlayerCommandPacket(this, ServerboundPlayerCommandPacket.Action.START_SNEAKING));
      } else {
         this.connection.send(new ServerboundPlayerCommandPacket(this, ServerboundPlayerCommandPacket.Action.STOP_SNEAKING));
      }

      this.wasTryingToSneak = bl2;
   }

   if (this.isControlledCamera()) {
      AABB lv = this.getBoundingBox();
      double d = this.x - this.xLast;
      double e = lv.minY - this.yLast1;
      double f = this.z - this.zLast;
      double g = this.yRot - this.yRotLast;
      double h = this.xRot - this.xRotLast;
      this.positionReminder++;
      boolean bl3 = d * d + e * e + f * f > 9.0E-4 || this.positionReminder >= 20;
      boolean bl4 = g != 0.0 || h != 0.0;
      if (this.isPassenger()) {
         this.connection.send(new ServerboundMovePlayerPacket.PosRot(this.velocityX, -999.0, this.velocityZ, this.yRot, this.xRot, this.onGround));
         bl3 = false;
      } else if (bl3 && bl4) {
         this.connection.send(new ServerboundMovePlayerPacket.PosRot(this.x, lv.minY, this.z, this.yRot, this.xRot, this.onGround));
      } else if (bl3) {
         this.connection.send(new ServerboundMovePlayerPacket.Pos(this.x, lv.minY, this.z, this.onGround));
      } else if (bl4) {
         this.connection.send(new ServerboundMovePlayerPacket.Rot(this.yRot, this.xRot, this.onGround));
      } else if (this.lastOnGround != this.onGround) {
         this.connection.send(new ServerboundMovePlayerPacket(this.onGround));
      }

      if (bl3) {
         this.xLast = this.x;
         this.yLast1 = lv.minY;
         this.zLast = this.z;
         this.positionReminder = 0;
      }

      if (bl4) {
         this.yRotLast = this.yRot;
         this.xRotLast = this.xRot;
      }

      this.lastOnGround = this.onGround;
      this.autoJumpEnabled = this.minecraft.options.autoJump;
   }
}

