      this.flyingSpeed = this.getSpeed() * 0.1F;
      if (this.isControlledByLocalInstance()) {
         this.setSpeed((float)this.getAttribute(SharedMonsterAttributes.MOVEMENT_SPEED).getValue());
         super.travel(f, g);
      } else if (lv instanceof Player) {
