private void floatBoat() {
   double d = -0.04F;
   double e = this.isNoGravity() ? 0.0 : -0.04F;
   double f = 0.0;
   this.invFriction = 0.05F;
   if (this.oldStatus == Boat.Status.IN_AIR && this.status != Boat.Status.IN_AIR && this.status != Boat.Status.ON_LAND) {
      this.waterLevel = this.getBoundingBox().minY + this.height;
      this.setPos(this.x, this.getWaterLevelAbove() - this.height + 0.101, this.z);
      this.velocityY = 0.0;
      this.lastYd = 0.0;
      this.status = Boat.Status.IN_WATER;
   } else {
      if (this.status == Boat.Status.IN_WATER) {
         f = (this.waterLevel - this.getBoundingBox().minY) / this.height;
         this.invFriction = 0.9F;
      } else if (this.status == Boat.Status.UNDER_FLOWING_WATER) {
         e = -7.0E-4;
         this.invFriction = 0.9F;
      } else if (this.status == Boat.Status.UNDER_WATER) {
         f = 0.01F;
         this.invFriction = 0.45F;
      } else if (this.status == Boat.Status.IN_AIR) {
         this.invFriction = 0.9F;
      } else if (this.status == Boat.Status.ON_LAND) {
         this.invFriction = this.landFriction;
         if (this.getControllingPassenger() instanceof Player) {
            this.landFriction /= 2.0F;
         }
      }

      this.velocityX = this.velocityX * this.invFriction;
      this.velocityZ = this.velocityZ * this.invFriction;
      this.deltaRotation = this.deltaRotation * this.invFriction;
      this.velocityY += e;
      if (f > 0.0) {
         double g = 0.65;
         this.velocityY += f * 0.06153846016296973;
         double h = 0.75;
         this.velocityY *= 0.75;
      }
   }
}

controlBoat.source:
private void controlBoat() {
   if (this.isVehicle()) {
      float f = 0.0F;
      if (this.inputLeft) {
         this.deltaRotation += -1.0F;
      }

      if (this.inputRight) {
         this.deltaRotation++;
      }

      if (this.inputRight != this.inputLeft && !this.inputUp && !this.inputDown) {
         f += 0.005F;
      }

      this.yRot = this.yRot + this.deltaRotation;
      if (this.inputUp) {
         f += 0.04F;
      }

      if (this.inputDown) {
         f -= 0.005F;
      }

      this.velocityX = this.velocityX + Mth.sin(-this.yRot * (float) (Math.PI / 180.0)) * f;
      this.velocityZ = this.velocityZ + Mth.cos(this.yRot * (float) (Math.PI / 180.0)) * f;
      this.setPaddleState(this.inputRight && !this.inputLeft || this.inputUp, this.inputLeft && !this.inputRight || this.inputUp);
   }
}

tick.source:
public void tick() {
   this.oldStatus = this.status;
   this.status = this.getStatus();
   if (this.status != Boat.Status.UNDER_WATER && this.status != Boat.Status.UNDER_FLOWING_WATER) {
      this.outOfControlTicks = 0.0F;
   } else {
      this.outOfControlTicks++;
   }

   if (!this.level.isClientSide && this.outOfControlTicks >= 60.0F) {
      this.ejectPassengers();
   }

   if (this.getHurtTime() > 0) {
      this.setHurtTime(this.getHurtTime() - 1);
   }

   if (this.getDamage() > 0.0F) {
      this.setDamage(this.getDamage() - 1.0F);
   }

   this.xo = this.x;
   this.yo = this.y;
   this.zo = this.z;
   super.tick();
   this.tickLerp();
   if (this.isControlledByLocalInstance()) {
      if (this.getPassengers().isEmpty() || !(this.getPassengers().get(0) instanceof Player)) {
         this.setPaddleState(false, false);
      }

      this.floatBoat();
      if (this.level.isClientSide) {
         this.controlBoat();
         this.level.sendPacketToServer(new ServerboundPaddleBoatPacket(this.getPaddleState(0), this.getPaddleState(1)));
      }

      this.move(MoverType.SELF, this.velocityX, this.velocityY, this.velocityZ);
   } else {
      this.velocityX = 0.0;
      this.velocityY = 0.0;
      this.velocityZ = 0.0;
   }

   this.tickBubbleColumn();

   for (int i = 0; i <= 1; i++) {
      if (this.getPaddleState(i)) {
         if (!this.isSilent()
            && this.paddlePositions[i] % (float) (Math.PI * 2) <= (float) (Math.PI / 4)
            && (this.paddlePositions[i] + (float) (Math.PI / 8)) % (float) (Math.PI * 2) >= (float) (Math.PI / 4)) {
            SoundEvent lv = this.getPaddleSound();
            if (lv != null) {
               Vec3 lv2 = this.getViewVector(1.0F);
               double d = i == 1 ? -lv2.z : lv2.z;
               double e = i == 1 ? lv2.x : -lv2.x;
               this.level.playSound(null, this.x + d, this.y, this.z + e, lv, this.getSoundSource(), 1.0F, 0.8F + 0.4F * this.random.nextFloat());
            }
         }

         this.paddlePositions[i] = (float)(this.paddlePositions[i] + (float) (Math.PI / 8));
      } else {
         this.paddlePositions[i] = 0.0F;
      }
   }

   this.checkInsideBlocks();
   List<Entity> list = this.level.getEntities(this, this.getBoundingBox().inflate(0.2F, -0.01F, 0.2F), EntitySelector.pushableBy(this));
   if (!list.isEmpty()) {
      boolean bl = !this.level.isClientSide && !(this.getControllingPassenger() instanceof Player);

      for (int j = 0; j < list.size(); j++) {
         Entity lv3 = list.get(j);
         if (!lv3.hasPassenger(this)) {
            if (bl
               && this.getPassengers().size() < 2
               && !lv3.isPassenger()
               && lv3.width < this.width
               && lv3 instanceof LivingEntity
               && !(lv3 instanceof WaterAnimal)
               && !(lv3 instanceof Player)) {
               lv3.startRiding(this);
            } else {
               this.push(lv3);
            }
         }
      }
   }
}

moveAlongTrack.source:
protected void moveAlongTrack(BlockPos arg, BlockState arg2) {
   this.fallDistance = 0.0F;
   Vec3 lv = this.getPos(this.x, this.y, this.z);
   this.y = arg.getY();
   boolean bl = false;
   boolean bl2 = false;
   BaseRailBlock lv2 = (BaseRailBlock)arg2.getBlock();
   if (lv2 == Blocks.POWERED_RAIL) {
      bl = arg2.getValue(PoweredRailBlock.POWERED);
      bl2 = !bl;
   }

   double d = 0.0078125;
   RailShape lv3 = arg2.getValue(lv2.getShapeProperty());
   switch (lv3) {
      case ASCENDING_EAST:
         this.velocityX -= 0.0078125;
         this.y++;
         break;
      case ASCENDING_WEST:
         this.velocityX += 0.0078125;
         this.y++;
         break;
      case ASCENDING_NORTH:
         this.velocityZ += 0.0078125;
         this.y++;
         break;
      case ASCENDING_SOUTH:
         this.velocityZ -= 0.0078125;
         this.y++;
   }

   int[][] is = EXITS[lv3.getData()];
   double e = is[1][0] - is[0][0];
   double f = is[1][2] - is[0][2];
   double g = Math.sqrt(e * e + f * f);
   double h = this.velocityX * e + this.velocityZ * f;
   if (h < 0.0) {
      e = -e;
      f = -f;
   }

   double i = Math.sqrt(this.velocityX * this.velocityX + this.velocityZ * this.velocityZ);
   if (i > 2.0) {
      i = 2.0;
   }

   this.velocityX = i * e / g;
   this.velocityZ = i * f / g;
   Entity lv4 = this.getPassengers().isEmpty() ? null : this.getPassengers().get(0);
   if (lv4 instanceof Player) {
      double j = ((Player)lv4).zza;
      if (j > 0.0) {
         double k = -Math.sin(lv4.yRot * (float) (Math.PI / 180.0));
         double l = Math.cos(lv4.yRot * (float) (Math.PI / 180.0));
         double m = this.velocityX * this.velocityX + this.velocityZ * this.velocityZ;
         if (m < 0.01) {
            this.velocityX += k * 0.1;
            this.velocityZ += l * 0.1;
            bl2 = false;
         }
      }
   }

   if (bl2) {
      double j = Math.sqrt(this.velocityX * this.velocityX + this.velocityZ * this.velocityZ);
      if (j < 0.03) {
         this.velocityX *= 0.0;
         this.velocityY *= 0.0;
         this.velocityZ *= 0.0;
      } else {
         this.velocityX *= 0.5;
         this.velocityY *= 0.0;
         this.velocityZ *= 0.5;
      }
   }

   double j = arg.getX() + 0.5 + is[0][0] * 0.5;
   double k = arg.getZ() + 0.5 + is[0][2] * 0.5;
   double l = arg.getX() + 0.5 + is[1][0] * 0.5;
   double m = arg.getZ() + 0.5 + is[1][2] * 0.5;
   e = l - j;
   f = m - k;
   double n;
   if (e == 0.0) {
      this.x = arg.getX() + 0.5;
      n = this.z - arg.getZ();
   } else if (f == 0.0) {
      this.z = arg.getZ() + 0.5;
      n = this.x - arg.getX();
   } else {
      double o = this.x - j;
      double p = this.z - k;
      n = (o * e + p * f) * 2.0;
   }

   this.x = j + e * n;
   this.z = k + f * n;
   this.setPos(this.x, this.y, this.z);
   double o = this.velocityX;
   double p = this.velocityZ;
   if (this.isVehicle()) {
      o *= 0.75;
      p *= 0.75;
   }

   double q = this.getMaxSpeed();
   o = Mth.clamp(o, -q, q);
   p = Mth.clamp(p, -q, q);
   this.move(MoverType.SELF, o, 0.0, p);
   if (is[0][1] != 0 && Mth.floor(this.x) - arg.getX() == is[0][0] && Mth.floor(this.z) - arg.getZ() == is[0][2]) {
      this.setPos(this.x, this.y + is[0][1], this.z);
   } else if (is[1][1] != 0 && Mth.floor(this.x) - arg.getX() == is[1][0] && Mth.floor(this.z) - arg.getZ() == is[1][2]) {
      this.setPos(this.x, this.y + is[1][1], this.z);
   }

   this.applyNaturalSlowdown();
   Vec3 lv5 = this.getPos(this.x, this.y, this.z);
   if (lv5 != null && lv != null) {
      double r = (lv.y - lv5.y) * 0.05;
      i = Math.sqrt(this.velocityX * this.velocityX + this.velocityZ * this.velocityZ);
      if (i > 0.0) {
         this.velocityX = this.velocityX / i * (i + r);
         this.velocityZ = this.velocityZ / i * (i + r);
      }

      this.setPos(this.x, lv5.y, this.z);
   }

   int s = Mth.floor(this.x);
   int t = Mth.floor(this.z);
   if (s != arg.getX() || t != arg.getZ()) {
      i = Math.sqrt(this.velocityX * this.velocityX + this.velocityZ * this.velocityZ);
      this.velocityX = i * (s - arg.getX());
      this.velocityZ = i * (t - arg.getZ());
   }

   if (bl) {
      double u = Math.sqrt(this.velocityX * this.velocityX + this.velocityZ * this.velocityZ);
      if (u > 0.01) {
         double v = 0.06;
         this.velocityX = this.velocityX + this.velocityX / u * 0.06;
         this.velocityZ = this.velocityZ + this.velocityZ / u * 0.06;
      } else if (lv3 == RailShape.EAST_WEST) {
         if (this.level.getBlockState(arg.west()).isRedstoneConductor()) {
            this.velocityX = 0.02;
         } else if (this.level.getBlockState(arg.east()).isRedstoneConductor()) {
            this.velocityX = -0.02;
         }
      } else if (lv3 == RailShape.NORTH_SOUTH) {
         if (this.level.getBlockState(arg.north()).isRedstoneConductor()) {
            this.velocityZ = 0.02;
         } else if (this.level.getBlockState(arg.south()).isRedstoneConductor()) {
            this.velocityZ = -0.02;
         }
      }
   }
}

tick.source:
public void tick() {
   if (this.getHurtTime() > 0) {
      this.setHurtTime(this.getHurtTime() - 1);
   }

   if (this.getDamage() > 0.0F) {
      this.setDamage(this.getDamage() - 1.0F);
   }

   if (this.y < -64.0) {
      this.outOfWorld();
   }

   if (!this.level.isClientSide && this.level instanceof ServerLevel) {
      this.level.profiler.push("portal");
      MinecraftServer minecraftServer = this.level.getServer();
      int i = this.getPortalWaitTime();
      if (this.isInsidePortal) {
         if (minecraftServer.isNetherEnabled()) {
            if (!this.isPassenger() && this.portalTime++ >= i) {
               this.portalTime = i;
               this.changingDimensionDelay = this.getDimensionChangingDelay();
               DimensionType lv;
               if (this.level.dimension.getType() == DimensionType.NETHER) {
                  lv = DimensionType.OVERWORLD;
               } else {
                  lv = DimensionType.NETHER;
               }

               this.changeDimension(lv);
            }

            this.isInsidePortal = false;
         }
      } else {
         if (this.portalTime > 0) {
            this.portalTime -= 4;
         }

         if (this.portalTime < 0) {
            this.portalTime = 0;
         }
      }

      if (this.changingDimensionDelay > 0) {
         this.changingDimensionDelay--;
      }

      this.level.profiler.pop();
   }

   if (this.level.isClientSide) {
      if (this.lSteps > 0) {
         double d = this.x + (this.lx - this.x) / this.lSteps;
         double e = this.y + (this.ly - this.y) / this.lSteps;
         double f = this.z + (this.lz - this.z) / this.lSteps;
         double g = Mth.wrapDegrees(this.lyr - this.yRot);
         this.yRot = (float)(this.yRot + g / this.lSteps);
         this.xRot = (float)(this.xRot + (this.lxr - this.xRot) / this.lSteps);
         this.lSteps--;
         this.setPos(d, e, f);
         this.setRot(this.yRot, this.xRot);
      } else {
         this.setPos(this.x, this.y, this.z);
         this.setRot(this.yRot, this.xRot);
      }
   } else {
      this.xo = this.x;
      this.yo = this.y;
      this.zo = this.z;
      if (!this.isNoGravity()) {
         this.velocityY -= 0.04F;
      }

      int j = Mth.floor(this.x);
      int i = Mth.floor(this.y);
      int k = Mth.floor(this.z);
      if (this.level.getBlockState(new BlockPos(j, i - 1, k)).is(BlockTags.RAILS)) {
         i--;
      }

      BlockPos lv2 = new BlockPos(j, i, k);
      BlockState lv3 = this.level.getBlockState(lv2);
      if (lv3.is(BlockTags.RAILS)) {
         this.moveAlongTrack(lv2, lv3);
         if (lv3.getBlock() == Blocks.ACTIVATOR_RAIL) {
            this.activateMinecart(j, i, k, lv3.getValue(PoweredRailBlock.POWERED));
         }
      } else {
         this.comeOffTrack();
      }

      this.checkInsideBlocks();
      this.xRot = 0.0F;
      double h = this.xo - this.x;
      double l = this.zo - this.z;
      if (h * h + l * l > 0.001) {
         this.yRot = (float)(Mth.atan2(l, h) * 180.0 / Math.PI);
         if (this.flipped) {
            this.yRot += 180.0F;
         }
      }

      double m = Mth.wrapDegrees(this.yRot - this.yRotO);
      if (m < -170.0 || m >= 170.0) {
         this.yRot += 180.0F;
         this.flipped = !this.flipped;
      }

      this.setRot(this.yRot, this.xRot);
      if (this.getMinecartType() == AbstractMinecart.Type.RIDEABLE && this.velocityX * this.velocityX + this.velocityZ * this.velocityZ > 0.01) {
         List<Entity> list = this.level.getEntities(this, this.getBoundingBox().inflate(0.2F, 0.0, 0.2F), EntitySelector.pushableBy(this));
         if (!list.isEmpty()) {
            for (int n = 0; n < list.size(); n++) {
               Entity lv4 = list.get(n);
               if (!(lv4 instanceof Player) && !(lv4 instanceof IronGolem) && !(lv4 instanceof AbstractMinecart) && !this.isVehicle() && !lv4.isPassenger()) {
                  lv4.startRiding(this);
               } else {
                  lv4.push(this);
               }
            }
         }
      } else {
         for (Entity lv5 : this.level.getEntities(this, this.getBoundingBox().inflate(0.2F, 0.0, 0.2F))) {
            if (!this.hasPassenger(lv5) && lv5.isPushable() && lv5 instanceof AbstractMinecart) {
               lv5.push(this);
            }
         }
      }

      this.updateInWaterState();
   }
}

travel.source:
public void travel(float f, float g, float h) {
   if (this.isVehicle() && this.canBeControlledByRider() && this.isSaddled()) {
      LivingEntity lv = (LivingEntity)this.getControllingPassenger();
      this.yRot = lv.yRot;
      this.yRotO = this.yRot;
      this.xRot = lv.xRot * 0.5F;
      this.setRot(this.yRot, this.xRot);
      this.yBodyRot = this.yRot;
      this.yHeadRot = this.yBodyRot;
      f = lv.xxa * 0.5F;
      h = lv.zza;
      if (h <= 0.0F) {
         h *= 0.25F;
         this.gallopSoundCounter = 0;
      }

      if (this.onGround && this.playerJumpPendingScale == 0.0F && this.isStanding() && !this.allowStandSliding) {
         f = 0.0F;
         h = 0.0F;
      }

      if (this.playerJumpPendingScale > 0.0F && !this.isJumping() && this.onGround) {
         this.velocityY = this.getCustomJump() * this.playerJumpPendingScale;
         if (this.hasEffect(MobEffects.JUMP)) {
            this.velocityY = this.velocityY + (this.getEffect(MobEffects.JUMP).getAmplifier() + 1) * 0.1F;
         }

         this.setIsJumping(true);
         this.hasImpulse = true;
         if (h > 0.0F) {
            float i = Mth.sin(this.yRot * (float) (Math.PI / 180.0));
            float j = Mth.cos(this.yRot * (float) (Math.PI / 180.0));
            this.velocityX = this.velocityX + -0.4F * i * this.playerJumpPendingScale;
            this.velocityZ = this.velocityZ + 0.4F * j * this.playerJumpPendingScale;
            this.playJumpSound();
         }

         this.playerJumpPendingScale = 0.0F;
      }

      this.flyingSpeed = this.getSpeed() * 0.1F;
      if (this.isControlledByLocalInstance()) {
         this.setSpeed((float)this.getAttribute(SharedMonsterAttributes.MOVEMENT_SPEED).getValue());
         super.travel(f, g, h);
      } else if (lv instanceof Player) {
         this.velocityX = 0.0;
         this.velocityY = 0.0;
         this.velocityZ = 0.0;
      }

      if (this.onGround) {
         this.playerJumpPendingScale = 0.0F;
         this.setIsJumping(false);
      }

      this.animationSpeedOld = this.animationSpeed;
      double d = this.x - this.xo;
      double e = this.z - this.zo;
      float k = Mth.sqrt(d * d + e * e) * 4.0F;
      if (k > 1.0F) {
         k = 1.0F;
      }

      this.animationSpeed = this.animationSpeed + (k - this.animationSpeed) * 0.4F;
      this.animationPosition = this.animationPosition + this.animationSpeed;
   } else {
      this.flyingSpeed = 0.02F;
      super.travel(f, g, h);
   }
}

rotateTowardsMovement.source:
public static final void rotateTowardsMovement(Entity arg, float f) {
   double d = arg.velocityX;
   double e = arg.velocityY;
   double g = arg.velocityZ;
   float h = Mth.sqrt(d * d + g * g);
   arg.yRot = (float)(Mth.atan2(g, d) * 180.0F / (float)Math.PI) + 90.0F;
   arg.xRot = (float)(Mth.atan2(h, e) * 180.0F / (float)Math.PI) - 90.0F;

   while (arg.xRot - arg.xRotO < -180.0F) {
      arg.xRotO -= 360.0F;
   }

   while (arg.xRot - arg.xRotO >= 180.0F) {
      arg.xRotO += 360.0F;
   }

   while (arg.yRot - arg.yRotO < -180.0F) {
      arg.yRotO -= 360.0F;
   }

   while (arg.yRot - arg.yRotO >= 180.0F) {
      arg.yRotO += 360.0F;
   }

   arg.xRot = arg.xRotO + (arg.xRot - arg.xRotO) * f;
   arg.yRot = arg.yRotO + (arg.yRot - arg.yRotO) * f;
}

tick.source:
public void tick() {
   this.xOld = this.x;
   this.yOld = this.y;
   this.zOld = this.z;
   super.tick();
   if (this.shakeTime > 0) {
      this.shakeTime--;
   }

