            f = Mth.sqrt(f);
            d /= f;
            e /= f;
            double g = 1.0 / f;
            if (g > 1.0) {
               g = 1.0;
            }

            d *= g;
            e *= g;
            d *= 0.05F;
            e *= 0.05F;
            d *= 1.0F - this.pushthrough;
            e *= 1.0F - this.pushthrough;
            if (!this.isVehicle()) {
