public void tick() {
   super.tick();
   if (this.shakeTime > 0) {
      this.shakeTime--;
   }

   if (this.inGround) {
      this.inGround = false;
      this.setDeltaMovement(this.getDeltaMovement().multiply(this.random.nextFloat() * 0.2F, this.random.nextFloat() * 0.2F, this.random.nextFloat() * 0.2F));
   }

   AABB lv = this.getBoundingBox().expandTowards(this.getDeltaMovement()).inflate(1.0);

   for (Entity lv2 : this.level.getEntities(this, lv, arg -> !arg.isSpectator() && arg.isPickable())) {
      if (lv2 == this.entityToIgnore) {
         this.timeToIgnore++;
         break;
      }

      if (this.owner != null && this.tickCount < 2 && this.entityToIgnore == null) {
         this.entityToIgnore = lv2;
         this.timeToIgnore = 3;
         break;
      }
   }

   HitResult lv3 = ProjectileUtil.getHitResult(
      this, lv, arg -> !arg.isSpectator() && arg.isPickable() && arg != this.entityToIgnore, ClipContext.Block.OUTLINE, true
   );
   if (this.entityToIgnore != null && this.timeToIgnore-- <= 0) {
      this.entityToIgnore = null;
   }

   if (lv3.getType() != HitResult.Type.MISS) {
      if (lv3.getType() == HitResult.Type.BLOCK && this.level.getBlockState(((BlockHitResult)lv3).getBlockPos()).getBlock() == Blocks.NETHER_PORTAL) {
         this.handleInsidePortal(((BlockHitResult)lv3).getBlockPos());
      } else {
         this.onHit(lv3);
      }
   }

   Vec3 lv4 = this.getDeltaMovement();
   double d = this.getX() + lv4.x;
   double e = this.getY() + lv4.y;
   double f = this.getZ() + lv4.z;
   float g = Mth.sqrt(getHorizontalDistanceSqr(lv4));
   this.yRot = (float)(Mth.atan2(lv4.x, lv4.z) * 180.0F / (float)Math.PI);
   this.xRot = (float)(Mth.atan2(lv4.y, g) * 180.0F / (float)Math.PI);

   while (this.xRot - this.xRotO < -180.0F) {
      this.xRotO -= 360.0F;
   }

   while (this.xRot - this.xRotO >= 180.0F) {
      this.xRotO += 360.0F;
   }

   while (this.yRot - this.yRotO < -180.0F) {
      this.yRotO -= 360.0F;
   }

   while (this.yRot - this.yRotO >= 180.0F) {
      this.yRotO += 360.0F;
   }

   this.xRot = Mth.lerp(0.2F, this.xRotO, this.xRot);
   this.yRot = Mth.lerp(0.2F, this.yRotO, this.yRot);
   float j;
   if (this.isInWater()) {
      for (int i = 0; i < 4; i++) {
         float h = 0.25F;
         this.level.addParticle(ParticleTypes.BUBBLE, d - lv4.x * 0.25, e - lv4.y * 0.25, f - lv4.z * 0.25, lv4.x, lv4.y, lv4.z);
      }

      j = 0.8F;
   } else {
      j = 0.99F;
   }

   this.setDeltaMovement(lv4.scale(j));
   if (!this.isNoGravity()) {
      Vec3 lv5 = this.getDeltaMovement();
      this.setDeltaMovement(lv5.x, lv5.y - this.getGravity(), lv5.z);
   }

   this.setPos(d, e, f);
}

public void tick() {
   super.tick();
   boolean bl = this.isNoPhysics();
   Vec3 lv = this.getDeltaMovement();
   if (this.xRotO == 0.0F && this.yRotO == 0.0F) {
      float f = Mth.sqrt(getHorizontalDistanceSqr(lv));
      this.yRot = (float)(Mth.atan2(lv.x, lv.z) * 180.0F / (float)Math.PI);
      this.xRot = (float)(Mth.atan2(lv.y, f) * 180.0F / (float)Math.PI);
      this.yRotO = this.yRot;
      this.xRotO = this.xRot;
   }

   BlockPos lv2 = new BlockPos(this);
   BlockState lv3 = this.level.getBlockState(lv2);
   if (!lv3.isAir() && !bl) {
      VoxelShape lv4 = lv3.getCollisionShape(this.level, lv2);
      if (!lv4.isEmpty()) {
         Vec3 lv5 = this.position();

         for (AABB lv6 : lv4.toAabbs()) {
            if (lv6.move(lv2).contains(lv5)) {
               this.inGround = true;
               break;
            }
         }
      }
   }

   if (this.shakeTime > 0) {
      this.shakeTime--;
   }

   if (this.isInWaterOrRain()) {
      this.clearFire();
   }

   if (this.inGround && !bl) {
      if (this.lastState != lv3 && this.level.noCollision(this.getBoundingBox().inflate(0.06))) {
         this.inGround = false;
         this.setDeltaMovement(lv.multiply(this.random.nextFloat() * 0.2F, this.random.nextFloat() * 0.2F, this.random.nextFloat() * 0.2F));
         this.life = 0;
         this.flightTime = 0;
      } else if (!this.level.isClientSide) {
         this.tickDespawn();
      }

      this.inGroundTime++;
   } else {
      this.inGroundTime = 0;
      this.flightTime++;
      Vec3 lv7 = this.position();
      Vec3 lv5 = lv7.add(lv);
      HitResult lv8 = this.level.clip(new ClipContext(lv7, lv5, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
      if (lv8.getType() != HitResult.Type.MISS) {
         lv5 = lv8.getLocation();
      }

      while (!this.removed) {
         EntityHitResult lv9 = this.findHitEntity(lv7, lv5);
         if (lv9 != null) {
            lv8 = lv9;
         }

         if (lv8 != null && lv8.getType() == HitResult.Type.ENTITY) {
            Entity lv10 = ((EntityHitResult)lv8).getEntity();
            Entity lv11 = this.getOwner();
            if (lv10 instanceof Player && lv11 instanceof Player && !((Player)lv11).canHarmPlayer((Player)lv10)) {
               lv8 = null;
               lv9 = null;
            }
         }

         if (lv8 != null && !bl) {
            this.onHit(lv8);
            this.hasImpulse = true;
         }

         if (lv9 == null || this.getPierceLevel() <= 0) {
            break;
         }

         lv8 = null;
      }

      lv = this.getDeltaMovement();
      double d = lv.x;
      double e = lv.y;
      double g = lv.z;
      if (this.isCritArrow()) {
         for (int i = 0; i < 4; i++) {
            this.level.addParticle(ParticleTypes.CRIT, this.getX() + d * i / 4.0, this.getY() + e * i / 4.0, this.getZ() + g * i / 4.0, -d, -e + 0.2, -g);
         }
      }

      double h = this.getX() + d;
      double j = this.getY() + e;
      double k = this.getZ() + g;
      float l = Mth.sqrt(getHorizontalDistanceSqr(lv));
      if (bl) {
         this.yRot = (float)(Mth.atan2(-d, -g) * 180.0F / (float)Math.PI);
      } else {
         this.yRot = (float)(Mth.atan2(d, g) * 180.0F / (float)Math.PI);
      }

      this.xRot = (float)(Mth.atan2(e, l) * 180.0F / (float)Math.PI);

      while (this.xRot - this.xRotO < -180.0F) {
         this.xRotO -= 360.0F;
      }

      while (this.xRot - this.xRotO >= 180.0F) {
         this.xRotO += 360.0F;
      }

      while (this.yRot - this.yRotO < -180.0F) {
         this.yRotO -= 360.0F;
      }

      while (this.yRot - this.yRotO >= 180.0F) {
         this.yRotO += 360.0F;
      }

      this.xRot = Mth.lerp(0.2F, this.xRotO, this.xRot);
      this.yRot = Mth.lerp(0.2F, this.yRotO, this.yRot);
      float m = 0.99F;
      float n = 0.05F;
      if (this.isInWater()) {
         for (int o = 0; o < 4; o++) {
            float p = 0.25F;
            this.level.addParticle(ParticleTypes.BUBBLE, h - d * 0.25, j - e * 0.25, k - g * 0.25, d, e, g);
         }

         m = this.getWaterInertia();
      }

      this.setDeltaMovement(lv.scale(m));
      if (!this.isNoGravity() && !bl) {
         Vec3 lv12 = this.getDeltaMovement();
         this.setDeltaMovement(lv12.x, lv12.y - 0.05F, lv12.z);
      }

      this.setPos(h, j, k);
      this.checkInsideBlocks();
   }
}

