tick.source:
public void tick() {
   if (this.level.isClientSide || (this.owner == null || !this.owner.removed) && this.level.hasChunkAt(new BlockPos(this))) {
      super.tick();
      if (this.shouldBurn()) {
         this.setSecondsOnFire(1);
      }

      this.flightTime++;
      HitResult lv = ProjectileUtil.forwardsRaycast(this, true, this.flightTime >= 25, this.owner, ClipContext.Block.COLLIDER);
      if (lv.getType() != HitResult.Type.MISS) {
         this.onHit(lv);
      }

      Vec3 lv2 = this.getDeltaMovement();
      double d = this.getX() + lv2.x;
      double e = this.getY() + lv2.y;
      double f = this.getZ() + lv2.z;
      ProjectileUtil.rotateTowardsMovement(this, 0.2F);
      float g = this.getInertia();
      if (this.isInWater()) {
         for (int i = 0; i < 4; i++) {
            float h = 0.25F;
            this.level.addParticle(ParticleTypes.BUBBLE, d - lv2.x * 0.25, e - lv2.y * 0.25, f - lv2.z * 0.25, lv2.x, lv2.y, lv2.z);
         }

         g = 0.8F;
      }

      this.setDeltaMovement(lv2.add(this.xPower, this.yPower, this.zPower).scale(g));
      this.level.addParticle(this.getTrailParticle(), d, e + 0.5, f, 0.0, 0.0, 0.0);
      this.setPos(d, e, f);
   } else {
      this.remove();
   }
}

public void tick() {
   super.tick();
   if (this.isAttachedToEntity()) {
      if (this.attachedToEntity == null) {
         this.entityData.get(DATA_ATTACHED_TO_TARGET).ifPresent(i -> {
            Entity lvx = this.level.getEntity(i);
            if (lvx instanceof LivingEntity) {
               this.attachedToEntity = (LivingEntity)lvx;
            }
         });
      }

      if (this.attachedToEntity != null) {
         if (this.attachedToEntity.isFallFlying()) {
            Vec3 lv = this.attachedToEntity.getLookAngle();
            double d = 1.5;
            double e = 0.1;
            Vec3 lv2 = this.attachedToEntity.getDeltaMovement();
            this.attachedToEntity
               .setDeltaMovement(
                  lv2.add(lv.x * 0.1 + (lv.x * 1.5 - lv2.x) * 0.5, lv.y * 0.1 + (lv.y * 1.5 - lv2.y) * 0.5, lv.z * 0.1 + (lv.z * 1.5 - lv2.z) * 0.5)
               );
         }

         this.setPos(this.attachedToEntity.getX(), this.attachedToEntity.getY(), this.attachedToEntity.getZ());
         this.setDeltaMovement(this.attachedToEntity.getDeltaMovement());
      }
   } else {
      if (!this.isShotAtAngle()) {
         this.setDeltaMovement(this.getDeltaMovement().multiply(1.15, 1.0, 1.15).add(0.0, 0.04, 0.0));
      }

      this.move(MoverType.SELF, this.getDeltaMovement());
   }

   Vec3 lv = this.getDeltaMovement();
   HitResult lv3 = ProjectileUtil.getHitResult(
      this,
      this.getBoundingBox().expandTowards(lv).inflate(1.0),
      arg -> !arg.isSpectator() && arg.isAlive() && arg.isPickable(),
      ClipContext.Block.COLLIDER,
      true
   );
   if (!this.noPhysics) {
      this.performHitChecks(lv3);
      this.hasImpulse = true;
   }

   float f = Mth.sqrt(getHorizontalDistanceSqr(lv));
   this.yRot = (float)(Mth.atan2(lv.x, lv.z) * 180.0F / (float)Math.PI);
   this.xRot = (float)(Mth.atan2(lv.y, f) * 180.0F / (float)Math.PI);

   while (this.xRot - this.xRotO < -180.0F) {
      this.xRotO -= 360.0F;
   }

   while (this.xRot - this.xRotO >= 180.0F) {
      this.xRotO += 360.0F;
   }

   while (this.yRot - this.yRotO < -180.0F) {
      this.yRotO -= 360.0F;
   }

   while (this.yRot - this.yRotO >= 180.0F) {
      this.yRotO += 360.0F;
   }

   this.xRot = Mth.lerp(0.2F, this.xRotO, this.xRot);
   this.yRot = Mth.lerp(0.2F, this.yRotO, this.yRot);
   if (this.life == 0 && !this.isSilent()) {
      this.level.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.FIREWORK_ROCKET_LAUNCH, SoundSource.AMBIENT, 3.0F, 1.0F);
   }

   this.life++;
   if (this.level.isClientSide && this.life % 2 < 2) {
      this.level
         .addParticle(
            ParticleTypes.FIREWORK,
            this.getX(),
            this.getY() - 0.3,
            this.getZ(),
            this.random.nextGaussian() * 0.05,
            -this.getDeltaMovement().y * 0.5,
            this.random.nextGaussian() * 0.05
         );
   }

   if (!this.level.isClientSide && this.life > this.lifetime) {
      this.explode();
   }
}

