travel.source:
public void travel(Vec3 arg) {
   if (this.isEffectiveAi() || this.isControlledByLocalInstance()) {
      double d = 0.08;
      boolean bl = this.getDeltaMovement().y <= 0.0;
      if (bl && this.hasEffect(MobEffects.SLOW_FALLING)) {
         d = 0.01;
         this.fallDistance = 0.0F;
      }

      if (!this.isInWater() || this instanceof Player && ((Player)this).abilities.flying) {
         if (!this.isInLava() || this instanceof Player && ((Player)this).abilities.flying) {
            if (this.isFallFlying()) {
               Vec3 lv4 = this.getDeltaMovement();
               if (lv4.y > -0.5) {
                  this.fallDistance = 1.0F;
               }

               Vec3 lv5 = this.getLookAngle();
               float f = this.xRot * (float) (Math.PI / 180.0);
               double j = Math.sqrt(lv5.x * lv5.x + lv5.z * lv5.z);
               double k = Math.sqrt(getHorizontalDistanceSqr(lv4));
               double i = lv5.length();
               float l = Mth.cos(f);
               l = (float)(l * (l * Math.min(1.0, i / 0.4)));
               lv4 = this.getDeltaMovement().add(0.0, d * (-1.0 + l * 0.75), 0.0);
               if (lv4.y < 0.0 && j > 0.0) {
                  double m = lv4.y * -0.1 * l;
                  lv4 = lv4.add(lv5.x * m / j, m, lv5.z * m / j);
               }

               if (f < 0.0F && j > 0.0) {
                  double m = k * -Mth.sin(f) * 0.04;
                  lv4 = lv4.add(-lv5.x * m / j, m * 3.2, -lv5.z * m / j);
               }

               if (j > 0.0) {
                  lv4 = lv4.add((lv5.x / j * k - lv4.x) * 0.1, 0.0, (lv5.z / j * k - lv4.z) * 0.1);
               }

               this.setDeltaMovement(lv4.multiply(0.99F, 0.98F, 0.99F));
               this.move(MoverType.SELF, this.getDeltaMovement());
               if (this.horizontalCollision && !this.level.isClientSide) {
                  double m = Math.sqrt(getHorizontalDistanceSqr(this.getDeltaMovement()));
                  double n = k - m;
                  float o = (float)(n * 10.0 - 3.0);
                  if (o > 0.0F) {
                     this.playSound(this.getFallDamageSound((int)o), 1.0F, 1.0F);
                     this.hurt(DamageSource.FLY_INTO_WALL, o);
                  }
               }

               if (this.onGround && !this.level.isClientSide) {
                  this.setSharedFlag(7, false);
               }
            } else {
               BlockPos lv6 = this.getBlockPosBelowThatAffectsMyMovement();
               float p = this.level.getBlockState(lv6).getBlock().getFriction();
               float f = this.onGround ? p * 0.91F : 0.91F;
               this.moveRelative(this.getFrictionInfluencedSpeed(p), arg);
               this.setDeltaMovement(this.handleOnClimbable(this.getDeltaMovement()));
               this.move(MoverType.SELF, this.getDeltaMovement());
               Vec3 lv7 = this.getDeltaMovement();
               if ((this.horizontalCollision || this.jumping) && this.onLadder()) {
                  lv7 = new Vec3(lv7.x, 0.2, lv7.z);
               }

               double q = lv7.y;
               if (this.hasEffect(MobEffects.LEVITATION)) {
                  q += (0.05 * (this.getEffect(MobEffects.LEVITATION).getAmplifier() + 1) - lv7.y) * 0.2;
                  this.fallDistance = 0.0F;
               } else if (this.level.isClientSide && !this.level.hasChunkAt(lv6)) {
                  if (this.getY() > 0.0) {
                     q = -0.1;
                  } else {
                     q = 0.0;
                  }
               } else if (!this.isNoGravity()) {
                  q -= d;
               }

               this.setDeltaMovement(lv7.x * f, q * 0.98F, lv7.z * f);
            }
         } else {
            double e = this.getY();
            this.moveRelative(0.02F, arg);
            this.move(MoverType.SELF, this.getDeltaMovement());
            this.setDeltaMovement(this.getDeltaMovement().scale(0.5));
            if (!this.isNoGravity()) {
               this.setDeltaMovement(this.getDeltaMovement().add(0.0, -d / 4.0, 0.0));
            }

            Vec3 lv3 = this.getDeltaMovement();
            if (this.horizontalCollision && this.isFree(lv3.x, lv3.y + 0.6F - this.getY() + e, lv3.z)) {
               this.setDeltaMovement(lv3.x, 0.3F, lv3.z);
            }
         }
      } else {
         double e = this.getY();
         float f = this.isSprinting() ? 0.9F : this.getWaterSlowDown();
         float g = 0.02F;
         float h = EnchantmentHelper.getDepthStrider(this);
         if (h > 3.0F) {
            h = 3.0F;
         }

         if (!this.onGround) {
            h *= 0.5F;
         }

         if (h > 0.0F) {
            f += (0.54600006F - f) * h / 3.0F;
            g += (this.getSpeed() - g) * h / 3.0F;
         }

         if (this.hasEffect(MobEffects.DOLPHINS_GRACE)) {
            f = 0.96F;
         }

         this.moveRelative(g, arg);
         this.move(MoverType.SELF, this.getDeltaMovement());
         Vec3 lv = this.getDeltaMovement();
         if (this.horizontalCollision && this.onLadder()) {
            lv = new Vec3(lv.x, 0.2, lv.z);
         }

         this.setDeltaMovement(lv.multiply(f, 0.8F, f));
         if (!this.isNoGravity() && !this.isSprinting()) {
            Vec3 lv2 = this.getDeltaMovement();
            double i;
            if (bl && Math.abs(lv2.y - 0.005) >= 0.003 && Math.abs(lv2.y - d / 16.0) < 0.003) {
               i = -0.003;
            } else {
               i = lv2.y - d / 16.0;
            }

            this.setDeltaMovement(lv2.x, i, lv2.z);
         }

         Vec3 lv2 = this.getDeltaMovement();
         if (this.horizontalCollision && this.isFree(lv2.x, lv2.y + 0.6F - this.getY() + e, lv2.z)) {
            this.setDeltaMovement(lv2.x, 0.3F, lv2.z);
         }
      }
   }

   this.animationSpeedOld = this.animationSpeed;
   double d = this.getX() - this.xo;
   double r = this.getZ() - this.zo;
   double s = this instanceof FlyingAnimal ? this.getY() - this.yo : 0.0;
   float g = Mth.sqrt(d * d + s * s + r * r) * 4.0F;
   if (g > 1.0F) {
      g = 1.0F;
   }

   this.animationSpeed = this.animationSpeed + (g - this.animationSpeed) * 0.4F;
   this.animationPosition = this.animationPosition + this.animationSpeed;
}

causeFallDamage.source:
public boolean causeFallDamage(float f, float g) {
   boolean bl = super.causeFallDamage(f, g);
   int i = this.calculateFallDamage(f, g);
   if (i > 0) {
      this.playSound(this.getFallDamageSound(i), 1.0F, 1.0F);
      this.playBlockFallSound();
      this.hurt(DamageSource.FALL, i);
      return true;
   } else {
      return bl;
   }
}

travel.source:
public void travel(Vec3 arg) {
   double d = this.getX();
   double e = this.getY();
   double f = this.getZ();
   if (this.isSwimming() && !this.isPassenger()) {
      double g = this.getLookAngle().y;
      double h = g < -0.2 ? 0.085 : 0.06;
      if (g <= 0.0 || this.jumping || !this.level.getBlockState(new BlockPos(this.getX(), this.getY() + 1.0 - 0.1, this.getZ())).getFluidState().isEmpty()) {
         Vec3 lv = this.getDeltaMovement();
         this.setDeltaMovement(lv.add(0.0, (g - lv.y) * h, 0.0));
      }
   }

   if (this.abilities.flying && !this.isPassenger()) {
      double g = this.getDeltaMovement().y;
      float i = this.flyingSpeed;
      this.flyingSpeed = this.abilities.getFlyingSpeed() * (this.isSprinting() ? 2 : 1);
      super.travel(arg);
      Vec3 lv2 = this.getDeltaMovement();
      this.setDeltaMovement(lv2.x, g * 0.6, lv2.z);
      this.flyingSpeed = i;
      this.fallDistance = 0.0F;
      this.setSharedFlag(7, false);
   } else {
      super.travel(arg);
   }

   this.checkMovementStatistics(this.getX() - d, this.getY() - e, this.getZ() - f);
}

aiStep.source:
public void aiStep() {
   if (this.jumpTriggerTime > 0) {
      this.jumpTriggerTime--;
   }

   if (this.level.getDifficulty() == Difficulty.PEACEFUL && this.level.getGameRules().getBoolean(GameRules.RULE_NATURAL_REGENERATION)) {
      if (this.getHealth() < this.getMaxHealth() && this.tickCount % 20 == 0) {
         this.heal(1.0F);
      }

      if (this.foodData.needsFood() && this.tickCount % 10 == 0) {
         this.foodData.setFoodLevel(this.foodData.getFoodLevel() + 1);
      }
   }

   this.inventory.tick();
   this.oBob = this.bob;
   super.aiStep();
   AttributeInstance lv = this.getAttribute(SharedMonsterAttributes.MOVEMENT_SPEED);
   if (!this.level.isClientSide) {
      lv.setBaseValue(this.abilities.getWalkingSpeed());
   }

   this.flyingSpeed = 0.02F;
   if (this.isSprinting()) {
      this.flyingSpeed = (float)(this.flyingSpeed + 0.005999999865889549);
   }

   this.setSpeed((float)lv.getValue());
   float f;
   if (this.onGround && !(this.getHealth() <= 0.0F) && !this.isSwimming()) {
      f = Math.min(0.1F, Mth.sqrt(getHorizontalDistanceSqr(this.getDeltaMovement())));
   } else {
      f = 0.0F;
   }

   this.bob = this.bob + (f - this.bob) * 0.4F;
   if (this.getHealth() > 0.0F && !this.isSpectator()) {
      AABB lv2;
      if (this.isPassenger() && !this.getVehicle().removed) {
         lv2 = this.getBoundingBox().minmax(this.getVehicle().getBoundingBox()).inflate(1.0, 0.0, 1.0);
      } else {
         lv2 = this.getBoundingBox().inflate(1.0, 0.5, 1.0);
      }

      List<Entity> list = this.level.getEntities(this, lv2);

      for (int i = 0; i < list.size(); i++) {
         Entity lv3 = list.get(i);
         if (!lv3.removed) {
            this.touch(lv3);
         }
      }
   }

   this.playShoulderEntityAmbientSound(this.getShoulderEntityLeft());
   this.playShoulderEntityAmbientSound(this.getShoulderEntityRight());
   if (!this.level.isClientSide && (this.fallDistance > 0.5F || this.isInWater()) || this.abilities.flying || this.isSleeping()) {
      this.removeEntitiesOnShoulder();
   }
}

rideTick.source:
public void rideTick() {
   if (!this.level.isClientSide && this.wantsToStopRiding() && this.isPassenger()) {
      this.stopRiding();
      this.setShiftKeyDown(false);
   } else {
      double d = this.getX();
      double e = this.getY();
      double f = this.getZ();
      float g = this.yRot;
      float h = this.xRot;
      super.rideTick();
      this.oBob = this.bob;
      this.bob = 0.0F;
      this.checkRidingStatistiscs(this.getX() - d, this.getY() - e, this.getZ() - f);
      if (this.getVehicle() instanceof Pig) {
