aiStep.source:
public void aiStep() {
   if (this.jumpTriggerTime > 0) {
      this.jumpTriggerTime--;
   }

   if (this.level.getDifficulty() == Difficulty.PEACEFUL && this.level.getGameRules().getBoolean(GameRules.RULE_NATURAL_REGENERATION)) {
      if (this.getHealth() < this.getMaxHealth() && this.tickCount % 20 == 0) {
         this.heal(1.0F);
      }

      if (this.foodData.needsFood() && this.tickCount % 10 == 0) {
         this.foodData.setFoodLevel(this.foodData.getFoodLevel() + 1);
      }
   }

   this.inventory.tick();
   this.oBob = this.bob;
   super.aiStep();
   AttributeInstance lv = this.getAttribute(SharedMonsterAttributes.MOVEMENT_SPEED);
   if (!this.level.isClientSide) {
      lv.setBaseValue(this.abilities.getWalkingSpeed());
   }

   this.flyingSpeed = 0.02F;
   if (this.isSprinting()) {
      this.flyingSpeed = (float)(this.flyingSpeed + 0.005999999865889549);
   }

   this.setSpeed((float)lv.getValue());
   float f;
   if (this.onGround && !(this.getHealth() <= 0.0F) && !this.isSwimming()) {
      f = Math.min(0.1F, Mth.sqrt(getHorizontalDistanceSqr(this.getDeltaMovement())));
   } else {
      f = 0.0F;
   }

   this.bob = this.bob + (f - this.bob) * 0.4F;
   if (this.getHealth() > 0.0F && !this.isSpectator()) {
      AABB lv2;
      if (this.isPassenger() && !this.getVehicle().removed) {
         lv2 = this.getBoundingBox().minmax(this.getVehicle().getBoundingBox()).inflate(1.0, 0.0, 1.0);
      } else {
         lv2 = this.getBoundingBox().inflate(1.0, 0.5, 1.0);
      }

      List<Entity> list = this.level.getEntities(this, lv2);

      for (int i = 0; i < list.size(); i++) {
         Entity lv3 = list.get(i);
         if (!lv3.removed) {
            this.touch(lv3);
         }
      }
   }

   this.playShoulderEntityAmbientSound(this.getShoulderEntityLeft());
   this.playShoulderEntityAmbientSound(this.getShoulderEntityRight());
   if (!this.level.isClientSide && (this.fallDistance > 0.5F || this.isInWater()) || this.abilities.flying || this.isSleeping()) {
      this.removeEntitiesOnShoulder();
   }
}

