move.source:
public void move(MoverType arg, Vec3 arg2) {
   if (this.noPhysics) {
      this.setBoundingBox(this.getBoundingBox().move(arg2));
      this.setLocationFromBoundingbox();
   } else {
      if (arg == MoverType.PISTON) {
         arg2 = this.limitPistonMovement(arg2);
         if (arg2.equals(Vec3.ZERO)) {
            return;
         }
      }

      this.level.getProfiler().push("move");
      if (this.stuckSpeedMultiplier.lengthSqr() > 1.0E-7) {
         arg2 = arg2.multiply(this.stuckSpeedMultiplier);
         this.stuckSpeedMultiplier = Vec3.ZERO;
         this.setDeltaMovement(Vec3.ZERO);
      }

      arg2 = this.maybeBackOffFromEdge(arg2, arg);
      Vec3 lv = this.collide(arg2);
      if (lv.lengthSqr() > 1.0E-7) {
         this.setBoundingBox(this.getBoundingBox().move(lv));
         this.setLocationFromBoundingbox();
      }

      this.level.getProfiler().pop();
      this.level.getProfiler().push("rest");
      this.horizontalCollision = !Mth.equal(arg2.x, lv.x) || !Mth.equal(arg2.z, lv.z);
      this.verticalCollision = arg2.y != lv.y;
      this.onGround = this.verticalCollision && arg2.y < 0.0;
      BlockPos lv2 = this.getOnPos();
      BlockState lv3 = this.level.getBlockState(lv2);
      this.checkFallDamage(lv.y, this.onGround, lv3, lv2);
      Vec3 lv4 = this.getDeltaMovement();
      if (arg2.x != lv.x) {
         this.setDeltaMovement(0.0, lv4.y, lv4.z);
      }

      if (arg2.z != lv.z) {
         this.setDeltaMovement(lv4.x, lv4.y, 0.0);
      }

      Block lv5 = lv3.getBlock();
      if (arg2.y != lv.y) {
         lv5.updateEntityAfterFallOn(this.level, this);
      }

      if (this.onGround && !this.isSteppingCarefully()) {
         lv5.stepOn(this.level, lv2, this);
      }

      if (this.isMovementNoisy() && !this.isPassenger()) {
         double d = lv.x;
         double e = lv.y;
         double f = lv.z;
         if (!lv5.is(BlockTags.CLIMBABLE)) {
            e = 0.0;
         }

         this.walkDist = (float)(this.walkDist + Mth.sqrt(getHorizontalDistanceSqr(lv)) * 0.6);
         this.moveDist = (float)(this.moveDist + Mth.sqrt(d * d + e * e + f * f) * 0.6);
         if (this.moveDist > this.nextStep && !lv3.isAir()) {
            this.nextStep = this.nextStep();
            if (this.isInWater()) {
               Entity lv6 = this.isVehicle() && this.getControllingPassenger() != null ? this.getControllingPassenger() : this;
               float g = lv6 == this ? 0.35F : 0.4F;
               Vec3 lv7 = lv6.getDeltaMovement();
               float h = Mth.sqrt(lv7.x * lv7.x * 0.2F + lv7.y * lv7.y + lv7.z * lv7.z * 0.2F) * g;
               if (h > 1.0F) {
                  h = 1.0F;
               }

               this.playSwimSound(h);
            } else {
               this.playStepSound(lv2, lv3);
            }
         } else if (this.moveDist > this.nextFlap && this.makeFlySound() && lv3.isAir()) {
            this.nextFlap = this.playFlySound(this.moveDist);
         }
      }

      try {
         this.isTouchingLava = false;
         this.checkInsideBlocks();
      } catch (Throwable throwable) {
         CrashReport lv8 = CrashReport.forThrowable(throwable, "Checking entity block collision");
         CrashReportCategory lv9 = lv8.addCategory("Entity being checked for collision");
         this.fillCrashReportCategory(lv9);
         throw new ReportedException(lv8);
      }

      float i = this.getBlockSpeedFactor();
      this.setDeltaMovement(this.getDeltaMovement().multiply(i, 1.0, i));
      if (this.level.getBlockStatesIfLoaded(this.getBoundingBox().deflate(0.001)).noneMatch(argx -> argx.is(BlockTags.FIRE) || argx.is(Blocks.LAVA))
         && this.remainingFireTicks <= 0) {
         this.setRemainingFireTicks(-this.getFireImmuneTicks());
      }

      if (this.isInWaterRainOrBubble() && this.isOnFire()) {
         this.playSound(SoundEvents.GENERIC_EXTINGUISH_FIRE, 0.7F, 1.6F + (this.random.nextFloat() - this.random.nextFloat()) * 0.4F);
         this.setRemainingFireTicks(-this.getFireImmuneTicks());
      }

      this.level.getProfiler().pop();
   }
}

collide.source:
private Vec3 collide(Vec3 arg) {
   AABB lv = this.getBoundingBox();
   CollisionContext lv2 = CollisionContext.of(this);
   VoxelShape lv3 = this.level.getWorldBorder().getCollisionShape();
   Stream<VoxelShape> stream = Shapes.joinIsNotEmpty(lv3, Shapes.create(lv.deflate(1.0E-7)), BooleanOp.AND) ? Stream.empty() : Stream.of(lv3);
   Stream<VoxelShape> stream2 = this.level.getEntityCollisions(this, lv.expandTowards(arg), argx -> true);
   RewindableStream<VoxelShape> lv4 = new RewindableStream<>(Stream.concat(stream2, stream));
   Vec3 lv5 = arg.lengthSqr() == 0.0 ? arg : collideBoundingBoxHeuristically(this, arg, lv, this.level, lv2, lv4);
   boolean bl = arg.x != lv5.x;
   boolean bl2 = arg.y != lv5.y;
   boolean bl3 = arg.z != lv5.z;
   boolean bl4 = this.onGround || bl2 && arg.y < 0.0;
   if (this.maxUpStep > 0.0F && bl4 && (bl || bl3)) {
      Vec3 lv6 = collideBoundingBoxHeuristically(this, new Vec3(arg.x, this.maxUpStep, arg.z), lv, this.level, lv2, lv4);
      Vec3 lv7 = collideBoundingBoxHeuristically(this, new Vec3(0.0, this.maxUpStep, 0.0), lv.expandTowards(arg.x, 0.0, arg.z), this.level, lv2, lv4);
      if (lv7.y < this.maxUpStep) {
         Vec3 lv8 = collideBoundingBoxHeuristically(this, new Vec3(arg.x, 0.0, arg.z), lv.move(lv7), this.level, lv2, lv4).add(lv7);
         if (getHorizontalDistanceSqr(lv8) > getHorizontalDistanceSqr(lv6)) {
            lv6 = lv8;
         }
      }

      if (getHorizontalDistanceSqr(lv6) > getHorizontalDistanceSqr(lv5)) {
         return lv6.add(collideBoundingBoxHeuristically(this, new Vec3(0.0, -lv6.y + arg.y, 0.0), lv.move(lv6), this.level, lv2, lv4));
      }
   }

   return lv5;
}

push.source:
public void push(Entity arg) {
   if (!this.isPassengerOfSameVehicle(arg)) {
      if (!arg.noPhysics && !this.noPhysics) {
         double d = arg.getX() - this.getX();
         double e = arg.getZ() - this.getZ();
         double f = Mth.absMax(d, e);
         if (f >= 0.01F) {
            f = Mth.sqrt(f);
            d /= f;
            e /= f;
            double g = 1.0 / f;
            if (g > 1.0) {
               g = 1.0;
            }

            d *= g;
            e *= g;
            d *= 0.05F;
            e *= 0.05F;
            d *= 1.0F - this.pushthrough;
            e *= 1.0F - this.pushthrough;
            if (!this.isVehicle()) {
               this.push(-d, 0.0, -e);
            }

            if (!arg.isVehicle()) {
               arg.push(d, 0.0, e);
            }
         }
      }
   }
}

public void push(double d, double e, double f) {
   this.setDeltaMovement(this.getDeltaMovement().add(d, e, f));
   this.hasImpulse = true;
}

