      this.setDeltaMovement(this.getDeltaMovement().scale(-0.1));
      this.yRot += 180.0F;
      this.yRotO += 180.0F;
      if (!this.level.isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7) {
