   this.xRot = lerpRotation(this.xRotO, (float)(Mth.atan2(lv.y, f) * 180.0F / (float)Math.PI));
   this.yRot = lerpRotation(this.yRotO, (float)(Mth.atan2(lv.x, lv.z) * 180.0F / (float)Math.PI));
