rotateTowardsMovement.source:
public static final void rotateTowardsMovement(Entity arg, float f) {
   Vec3 lv = arg.getDeltaMovement();
   if (lv.lengthSqr() != 0.0) {
      float g = Mth.sqrt(Entity.getHorizontalDistanceSqr(lv));
      arg.yRot = (float)(Mth.atan2(lv.z, lv.x) * 180.0F / (float)Math.PI) + 90.0F;
      arg.xRot = (float)(Mth.atan2(g, lv.y) * 180.0F / (float)Math.PI) - 90.0F;

      while (arg.xRot - arg.xRotO < -180.0F) {
         arg.xRotO -= 360.0F;
      }

      while (arg.xRot - arg.xRotO >= 180.0F) {
         arg.xRotO += 360.0F;
      }

      while (arg.yRot - arg.yRotO < -180.0F) {
         arg.yRotO -= 360.0F;
      }

      while (arg.yRot - arg.yRotO >= 180.0F) {
         arg.yRotO += 360.0F;
      }

      arg.xRot = Mth.lerp(f, arg.xRotO, arg.xRot);
      arg.yRot = Mth.lerp(f, arg.yRotO, arg.yRot);
   }
}

