aiStep.source:
public void aiStep() {
   this.sprintTime++;
   if (this.sprintTriggerTime > 0) {
      this.sprintTriggerTime--;
   }

   this.handleNetherPortalClient();
   boolean bl = this.input.jumping;
   boolean bl2 = this.input.shiftKeyDown;
   boolean bl3 = this.hasEnoughImpulseToStartSprinting();
   this.crouching = !this.abilities.flying
      && !this.isSwimming()
      && this.canEnterPose(Pose.CROUCHING)
      && (this.isShiftKeyDown() || !this.isSleeping() && !this.canEnterPose(Pose.STANDING));
   this.input.tick(this.isMovingSlowly());
   this.minecraft.getTutorial().onInput(this.input);
   if (this.isUsingItem() && !this.isPassenger()) {
      this.input.leftImpulse *= 0.2F;
      this.input.forwardImpulse *= 0.2F;
      this.sprintTriggerTime = 0;
   }

   boolean bl4 = false;
   if (this.autoJumpTime > 0) {
      this.autoJumpTime--;
      bl4 = true;
      this.input.jumping = true;
   }

   if (!this.noPhysics) {
      this.moveTowardsClosestSpace(this.getX() - this.getBbWidth() * 0.35, this.getZ() + this.getBbWidth() * 0.35);
      this.moveTowardsClosestSpace(this.getX() - this.getBbWidth() * 0.35, this.getZ() - this.getBbWidth() * 0.35);
      this.moveTowardsClosestSpace(this.getX() + this.getBbWidth() * 0.35, this.getZ() - this.getBbWidth() * 0.35);
      this.moveTowardsClosestSpace(this.getX() + this.getBbWidth() * 0.35, this.getZ() + this.getBbWidth() * 0.35);
   }

   if (bl2) {
      this.sprintTriggerTime = 0;
   }

   boolean bl5 = this.getFoodData().getFoodLevel() > 6.0F || this.abilities.mayfly;
   if ((this.onGround || this.isUnderWater())
      && !bl2
      && !bl3
      && this.hasEnoughImpulseToStartSprinting()
      && !this.isSprinting()
      && bl5
      && !this.isUsingItem()
      && !this.hasEffect(MobEffects.BLINDNESS)) {
      if (this.sprintTriggerTime <= 0 && !this.minecraft.options.keySprint.isDown()) {
         this.sprintTriggerTime = 7;
      } else {
         this.setSprinting(true);
      }
   }

   if (!this.isSprinting()
      && (!this.isInWater() || this.isUnderWater())
      && this.hasEnoughImpulseToStartSprinting()
      && bl5
      && !this.isUsingItem()
      && !this.hasEffect(MobEffects.BLINDNESS)
      && this.minecraft.options.keySprint.isDown()) {
      this.setSprinting(true);
   }

   if (this.isSprinting()) {
      boolean bl6 = !this.input.hasForwardImpulse() || !bl5;
      boolean bl7 = bl6 || this.horizontalCollision || this.isInWater() && !this.isUnderWater();
      if (this.isSwimming()) {
         if (!this.onGround && !this.input.shiftKeyDown && bl6 || !this.isInWater()) {
            this.setSprinting(false);
         }
      } else if (bl7) {
         this.setSprinting(false);
      }
   }

   boolean bl6 = false;
   if (this.abilities.mayfly) {
      if (this.minecraft.gameMode.isAlwaysFlying()) {
         if (!this.abilities.flying) {
            this.abilities.flying = true;
            bl6 = true;
            this.onUpdateAbilities();
         }
      } else if (!bl && this.input.jumping && !bl4) {
         if (this.jumpTriggerTime == 0) {
            this.jumpTriggerTime = 7;
         } else if (!this.isSwimming()) {
            this.abilities.flying = !this.abilities.flying;
            bl6 = true;
            this.onUpdateAbilities();
            this.jumpTriggerTime = 0;
         }
      }
   }

   if (this.input.jumping && !bl6 && !bl && !this.abilities.flying && !this.isPassenger() && !this.onClimbable()) {
      ItemStack lv = this.getItemBySlot(EquipmentSlot.CHEST);
      if (lv.getItem() == Items.ELYTRA && ElytraItem.isFlyEnabled(lv) && this.tryToStartFallFlying()) {
         this.connection.send(new ServerboundPlayerCommandPacket(this, ServerboundPlayerCommandPacket.Action.START_FALL_FLYING));
      }
   }

   this.wasFallFlying = this.isFallFlying();
   if (this.isInWater() && this.input.shiftKeyDown && this.isAffectedByFluids()) {
      this.goDownInWater();
   }

   if (this.isEyeInFluid(FluidTags.WATER)) {
      int i = this.isSpectator() ? 10 : 1;
      this.waterVisionTime = Mth.clamp(this.waterVisionTime + i, 0, 600);
   } else if (this.waterVisionTime > 0) {
      this.isEyeInFluid(FluidTags.WATER);
      this.waterVisionTime = Mth.clamp(this.waterVisionTime - 10, 0, 600);
   }

   if (this.abilities.flying && this.isControlledCamera()) {
      int i = 0;
      if (this.input.shiftKeyDown) {
         i--;
      }

      if (this.input.jumping) {
         i++;
      }

      if (i != 0) {
         this.setDeltaMovement(this.getDeltaMovement().add(0.0, i * this.abilities.getFlyingSpeed() * 3.0F, 0.0));
      }
   }

   if (this.isRidingJumpable()) {
      PlayerRideableJumping lv2 = (PlayerRideableJumping)this.getVehicle();
      if (this.jumpRidingTicks < 0) {
         this.jumpRidingTicks++;
         if (this.jumpRidingTicks == 0) {
            this.jumpRidingScale = 0.0F;
         }
      }

      if (bl && !this.input.jumping) {
         this.jumpRidingTicks = -10;
         lv2.onPlayerJump(Mth.floor(this.getJumpRidingScale() * 100.0F));
         this.sendRidingJump();
      } else if (!bl && this.input.jumping) {
         this.jumpRidingTicks = 0;
         this.jumpRidingScale = 0.0F;
      } else if (bl) {
         this.jumpRidingTicks++;
         if (this.jumpRidingTicks < 10) {
            this.jumpRidingScale = this.jumpRidingTicks * 0.1F;
         } else {
            this.jumpRidingScale = 0.8F + 2.0F / (this.jumpRidingTicks - 9) * 0.1F;
         }
      }
   } else {
      this.jumpRidingScale = 0.0F;
   }

   super.aiStep();
   if (this.onGround && this.abilities.flying && !this.minecraft.gameMode.isAlwaysFlying()) {
      this.abilities.flying = false;
      this.onUpdateAbilities();
   }
}

sendPosition.source:
private void sendPosition() {
   boolean bl = this.isSprinting();
   if (bl != this.wasSprinting) {
      ServerboundPlayerCommandPacket.Action lv = bl
         ? ServerboundPlayerCommandPacket.Action.START_SPRINTING
         : ServerboundPlayerCommandPacket.Action.STOP_SPRINTING;
      this.connection.send(new ServerboundPlayerCommandPacket(this, lv));
      this.wasSprinting = bl;
   }

   boolean bl2 = this.isShiftKeyDown();
   if (bl2 != this.wasShiftKeyDown) {
      ServerboundPlayerCommandPacket.Action lv2 = bl2
         ? ServerboundPlayerCommandPacket.Action.PRESS_SHIFT_KEY
         : ServerboundPlayerCommandPacket.Action.RELEASE_SHIFT_KEY;
      this.connection.send(new ServerboundPlayerCommandPacket(this, lv2));
      this.wasShiftKeyDown = bl2;
   }

   if (this.isControlledCamera()) {
      double d = this.getX() - this.xLast;
      double e = this.getY() - this.yLast1;
      double f = this.getZ() - this.zLast;
      double g = this.yRot - this.yRotLast;
      double h = this.xRot - this.xRotLast;
      this.positionReminder++;
      boolean bl3 = d * d + e * e + f * f > 9.0E-4 || this.positionReminder >= 20;
      boolean bl4 = g != 0.0 || h != 0.0;
      if (this.isPassenger()) {
         Vec3 lv3 = this.getDeltaMovement();
         this.connection.send(new ServerboundMovePlayerPacket.PosRot(lv3.x, -999.0, lv3.z, this.yRot, this.xRot, this.onGround));
         bl3 = false;
      } else if (bl3 && bl4) {
         this.connection.send(new ServerboundMovePlayerPacket.PosRot(this.getX(), this.getY(), this.getZ(), this.yRot, this.xRot, this.onGround));
      } else if (bl3) {
         this.connection.send(new ServerboundMovePlayerPacket.Pos(this.getX(), this.getY(), this.getZ(), this.onGround));
      } else if (bl4) {
         this.connection.send(new ServerboundMovePlayerPacket.Rot(this.yRot, this.xRot, this.onGround));
      } else if (this.lastOnGround != this.onGround) {
         this.connection.send(new ServerboundMovePlayerPacket(this.onGround));
      }

      if (bl3) {
         this.xLast = this.getX();
         this.yLast1 = this.getY();
         this.zLast = this.getZ();
         this.positionReminder = 0;
      }

      if (bl4) {
         this.yRotLast = this.yRot;
         this.xRotLast = this.xRot;
      }

      this.lastOnGround = this.onGround;
      this.autoJumpEnabled = this.minecraft.options.autoJump;
   }
}

floatBoat.source:
private void floatBoat() {
   double d = -0.04F;
   double e = this.isNoGravity() ? 0.0 : -0.04F;
   double f = 0.0;
   this.invFriction = 0.05F;
   if (this.oldStatus == Boat.Status.IN_AIR && this.status != Boat.Status.IN_AIR && this.status != Boat.Status.ON_LAND) {
      this.waterLevel = this.getY(1.0);
      this.setPos(this.getX(), this.getWaterLevelAbove() - this.getBbHeight() + 0.101, this.getZ());
      this.setDeltaMovement(this.getDeltaMovement().multiply(1.0, 0.0, 1.0));
      this.lastYd = 0.0;
      this.status = Boat.Status.IN_WATER;
   } else {
      if (this.status == Boat.Status.IN_WATER) {
         f = (this.waterLevel - this.getY()) / this.getBbHeight();
         this.invFriction = 0.9F;
      } else if (this.status == Boat.Status.UNDER_FLOWING_WATER) {
         e = -7.0E-4;
         this.invFriction = 0.9F;
      } else if (this.status == Boat.Status.UNDER_WATER) {
         f = 0.01F;
         this.invFriction = 0.45F;
      } else if (this.status == Boat.Status.IN_AIR) {
         this.invFriction = 0.9F;
      } else if (this.status == Boat.Status.ON_LAND) {
         this.invFriction = this.landFriction;
         if (this.getControllingPassenger() instanceof Player) {
            this.landFriction /= 2.0F;
         }
      }

      Vec3 lv = this.getDeltaMovement();
      this.setDeltaMovement(lv.x * this.invFriction, lv.y + e, lv.z * this.invFriction);
      this.deltaRotation = this.deltaRotation * this.invFriction;
      if (f > 0.0) {
         Vec3 lv2 = this.getDeltaMovement();
         this.setDeltaMovement(lv2.x, (lv2.y + f * 0.06153846016296973) * 0.75, lv2.z);
      }
   }
}

controlBoat.source:
private void controlBoat() {
   if (this.isVehicle()) {
      float f = 0.0F;
      if (this.inputLeft) {
         this.deltaRotation--;
      }

      if (this.inputRight) {
         this.deltaRotation++;
      }

      if (this.inputRight != this.inputLeft && !this.inputUp && !this.inputDown) {
         f += 0.005F;
      }

      this.yRot = this.yRot + this.deltaRotation;
      if (this.inputUp) {
         f += 0.04F;
      }

      if (this.inputDown) {
         f -= 0.005F;
      }

      this.setDeltaMovement(
         this.getDeltaMovement().add(Mth.sin(-this.yRot * (float) (Math.PI / 180.0)) * f, 0.0, Mth.cos(this.yRot * (float) (Math.PI / 180.0)) * f)
      );
      this.setPaddleState(this.inputRight && !this.inputLeft || this.inputUp, this.inputLeft && !this.inputRight || this.inputUp);
   }
}

tick.source:
public void tick() {
   this.oldStatus = this.status;
   this.status = this.getStatus();
   if (this.status != Boat.Status.UNDER_WATER && this.status != Boat.Status.UNDER_FLOWING_WATER) {
      this.outOfControlTicks = 0.0F;
   } else {
      this.outOfControlTicks++;
   }

   if (!this.level.isClientSide && this.outOfControlTicks >= 60.0F) {
      this.ejectPassengers();
   }

   if (this.getHurtTime() > 0) {
      this.setHurtTime(this.getHurtTime() - 1);
   }

   if (this.getDamage() > 0.0F) {
      this.setDamage(this.getDamage() - 1.0F);
   }

   super.tick();
   this.tickLerp();
   if (this.isControlledByLocalInstance()) {
      if (this.getPassengers().isEmpty() || !(this.getPassengers().get(0) instanceof Player)) {
         this.setPaddleState(false, false);
      }

      this.floatBoat();
      if (this.level.isClientSide) {
         this.controlBoat();
         this.level.sendPacketToServer(new ServerboundPaddleBoatPacket(this.getPaddleState(0), this.getPaddleState(1)));
      }

      this.move(MoverType.SELF, this.getDeltaMovement());
   } else {
      this.setDeltaMovement(Vec3.ZERO);
   }

   this.tickBubbleColumn();

   for (int i = 0; i <= 1; i++) {
      if (this.getPaddleState(i)) {
         if (!this.isSilent()
            && this.paddlePositions[i] % (float) (Math.PI * 2) <= (float) (Math.PI / 4)
            && (this.paddlePositions[i] + (float) (Math.PI / 8)) % (float) (Math.PI * 2) >= (float) (Math.PI / 4)) {
            SoundEvent lv = this.getPaddleSound();
            if (lv != null) {
               Vec3 lv2 = this.getViewVector(1.0F);
               double d = i == 1 ? -lv2.z : lv2.z;
               double e = i == 1 ? lv2.x : -lv2.x;
               this.level
                  .playSound(null, this.getX() + d, this.getY(), this.getZ() + e, lv, this.getSoundSource(), 1.0F, 0.8F + 0.4F * this.random.nextFloat());
            }
         }

         this.paddlePositions[i] = (float)(this.paddlePositions[i] + (float) (Math.PI / 8));
      } else {
         this.paddlePositions[i] = 0.0F;
      }
   }

   this.checkInsideBlocks();
   List<Entity> list = this.level.getEntities(this, this.getBoundingBox().inflate(0.2F, -0.01F, 0.2F), EntitySelector.pushableBy(this));
   if (!list.isEmpty()) {
      boolean bl = !this.level.isClientSide && !(this.getControllingPassenger() instanceof Player);

      for (int j = 0; j < list.size(); j++) {
         Entity lv3 = list.get(j);
         if (!lv3.hasPassenger(this)) {
            if (bl
               && this.getPassengers().size() < 2
               && !lv3.isPassenger()
               && lv3.getBbWidth() < this.getBbWidth()
               && lv3 instanceof LivingEntity
               && !(lv3 instanceof WaterAnimal)
               && !(lv3 instanceof Player)) {
               lv3.startRiding(this);
            } else {
               this.push(lv3);
            }
         }
      }
   }
}

moveAlongTrack.source:
protected void moveAlongTrack(BlockPos arg, BlockState arg2) {
   this.fallDistance = 0.0F;
   double d = this.getX();
   double e = this.getY();
   double f = this.getZ();
   Vec3 lv = this.getPos(d, e, f);
   e = arg.getY();
   boolean bl = false;
   boolean bl2 = false;
   BaseRailBlock lv2 = (BaseRailBlock)arg2.getBlock();
   if (lv2 == Blocks.POWERED_RAIL) {
      bl = arg2.getValue(PoweredRailBlock.POWERED);
      bl2 = !bl;
   }

   double g = 0.0078125;
   Vec3 lv3 = this.getDeltaMovement();
   RailShape lv4 = arg2.getValue(lv2.getShapeProperty());
   switch (lv4) {
      case ASCENDING_EAST:
         this.setDeltaMovement(lv3.add(-0.0078125, 0.0, 0.0));
         e++;
         break;
      case ASCENDING_WEST:
         this.setDeltaMovement(lv3.add(0.0078125, 0.0, 0.0));
         e++;
         break;
      case ASCENDING_NORTH:
         this.setDeltaMovement(lv3.add(0.0, 0.0, 0.0078125));
         e++;
         break;
      case ASCENDING_SOUTH:
         this.setDeltaMovement(lv3.add(0.0, 0.0, -0.0078125));
         e++;
   }

   lv3 = this.getDeltaMovement();
   Pair<Vec3i, Vec3i> pair = exits(lv4);
   Vec3i lv5 = (Vec3i)pair.getFirst();
   Vec3i lv6 = (Vec3i)pair.getSecond();
   double h = lv6.getX() - lv5.getX();
   double i = lv6.getZ() - lv5.getZ();
   double j = Math.sqrt(h * h + i * i);
   double k = lv3.x * h + lv3.z * i;
   if (k < 0.0) {
      h = -h;
      i = -i;
   }

   double l = Math.min(2.0, Math.sqrt(getHorizontalDistanceSqr(lv3)));
   lv3 = new Vec3(l * h / j, lv3.y, l * i / j);
   this.setDeltaMovement(lv3);
   Entity lv7 = this.getPassengers().isEmpty() ? null : this.getPassengers().get(0);
   if (lv7 instanceof Player) {
      Vec3 lv8 = lv7.getDeltaMovement();
      double m = getHorizontalDistanceSqr(lv8);
      double n = getHorizontalDistanceSqr(this.getDeltaMovement());
      if (m > 1.0E-4 && n < 0.01) {
         this.setDeltaMovement(this.getDeltaMovement().add(lv8.x * 0.1, 0.0, lv8.z * 0.1));
         bl2 = false;
      }
   }

   if (bl2) {
      double o = Math.sqrt(getHorizontalDistanceSqr(this.getDeltaMovement()));
      if (o < 0.03) {
         this.setDeltaMovement(Vec3.ZERO);
      } else {
         this.setDeltaMovement(this.getDeltaMovement().multiply(0.5, 0.0, 0.5));
      }
   }

   double o = arg.getX() + 0.5 + lv5.getX() * 0.5;
   double p = arg.getZ() + 0.5 + lv5.getZ() * 0.5;
   double q = arg.getX() + 0.5 + lv6.getX() * 0.5;
   double r = arg.getZ() + 0.5 + lv6.getZ() * 0.5;
   h = q - o;
   i = r - p;
   double s;
   if (h == 0.0) {
      s = f - arg.getZ();
   } else if (i == 0.0) {
      s = d - arg.getX();
   } else {
      double t = d - o;
      double u = f - p;
      s = (t * h + u * i) * 2.0;
   }

   d = o + h * s;
   f = p + i * s;
   this.setPos(d, e, f);
   double t = this.isVehicle() ? 0.75 : 1.0;
   double u = this.getMaxSpeed();
   lv3 = this.getDeltaMovement();
   this.move(MoverType.SELF, new Vec3(Mth.clamp(t * lv3.x, -u, u), 0.0, Mth.clamp(t * lv3.z, -u, u)));
   if (lv5.getY() != 0 && Mth.floor(this.getX()) - arg.getX() == lv5.getX() && Mth.floor(this.getZ()) - arg.getZ() == lv5.getZ()) {
      this.setPos(this.getX(), this.getY() + lv5.getY(), this.getZ());
   } else if (lv6.getY() != 0 && Mth.floor(this.getX()) - arg.getX() == lv6.getX() && Mth.floor(this.getZ()) - arg.getZ() == lv6.getZ()) {
      this.setPos(this.getX(), this.getY() + lv6.getY(), this.getZ());
   }

   this.applyNaturalSlowdown();
   Vec3 lv9 = this.getPos(this.getX(), this.getY(), this.getZ());
   if (lv9 != null && lv != null) {
      double v = (lv.y - lv9.y) * 0.05;
      Vec3 lv10 = this.getDeltaMovement();
      double w = Math.sqrt(getHorizontalDistanceSqr(lv10));
      if (w > 0.0) {
         this.setDeltaMovement(lv10.multiply((w + v) / w, 1.0, (w + v) / w));
      }

      this.setPos(this.getX(), lv9.y, this.getZ());
   }

   int x = Mth.floor(this.getX());
   int y = Mth.floor(this.getZ());
   if (x != arg.getX() || y != arg.getZ()) {
      Vec3 lv10 = this.getDeltaMovement();
      double w = Math.sqrt(getHorizontalDistanceSqr(lv10));
      this.setDeltaMovement(w * (x - arg.getX()), lv10.y, w * (y - arg.getZ()));
   }

   if (bl) {
      Vec3 lv10 = this.getDeltaMovement();
      double w = Math.sqrt(getHorizontalDistanceSqr(lv10));
      if (w > 0.01) {
         double z = 0.06;
         this.setDeltaMovement(lv10.add(lv10.x / w * 0.06, 0.0, lv10.z / w * 0.06));
      } else {
         Vec3 lv11 = this.getDeltaMovement();
         double aa = lv11.x;
         double ab = lv11.z;
         if (lv4 == RailShape.EAST_WEST) {
            if (this.isRedstoneConductor(arg.west())) {
               aa = 0.02;
            } else if (this.isRedstoneConductor(arg.east())) {
               aa = -0.02;
            }
         } else {
            if (lv4 != RailShape.NORTH_SOUTH) {
               return;
            }

            if (this.isRedstoneConductor(arg.north())) {
               ab = 0.02;
            } else if (this.isRedstoneConductor(arg.south())) {
               ab = -0.02;
            }
         }

         this.setDeltaMovement(aa, lv11.y, ab);
      }
   }
}

tick.source:
public void tick() {
   if (this.getHurtTime() > 0) {
      this.setHurtTime(this.getHurtTime() - 1);
   }

   if (this.getDamage() > 0.0F) {
      this.setDamage(this.getDamage() - 1.0F);
   }

   if (this.getY() < -64.0) {
      this.outOfWorld();
   }

   this.handleNetherPortal();
   if (this.level.isClientSide) {
      if (this.lSteps > 0) {
         double d = this.getX() + (this.lx - this.getX()) / this.lSteps;
         double e = this.getY() + (this.ly - this.getY()) / this.lSteps;
         double f = this.getZ() + (this.lz - this.getZ()) / this.lSteps;
         double g = Mth.wrapDegrees(this.lyr - this.yRot);
         this.yRot = (float)(this.yRot + g / this.lSteps);
         this.xRot = (float)(this.xRot + (this.lxr - this.xRot) / this.lSteps);
         this.lSteps--;
         this.setPos(d, e, f);
         this.setRot(this.yRot, this.xRot);
      } else {
         this.reapplyPosition();
         this.setRot(this.yRot, this.xRot);
      }
   } else {
      if (!this.isNoGravity()) {
         this.setDeltaMovement(this.getDeltaMovement().add(0.0, -0.04, 0.0));
      }

      int i = Mth.floor(this.getX());
      int j = Mth.floor(this.getY());
      int k = Mth.floor(this.getZ());
      if (this.level.getBlockState(new BlockPos(i, j - 1, k)).is(BlockTags.RAILS)) {
         j--;
      }

      BlockPos lv = new BlockPos(i, j, k);
      BlockState lv2 = this.level.getBlockState(lv);
      if (BaseRailBlock.isRail(lv2)) {
         this.moveAlongTrack(lv, lv2);
         if (lv2.is(Blocks.ACTIVATOR_RAIL)) {
            this.activateMinecart(i, j, k, lv2.getValue(PoweredRailBlock.POWERED));
         }
      } else {
         this.comeOffTrack();
      }

      this.checkInsideBlocks();
      this.xRot = 0.0F;
      double h = this.xo - this.getX();
      double l = this.zo - this.getZ();
      if (h * h + l * l > 0.001) {
         this.yRot = (float)(Mth.atan2(l, h) * 180.0 / Math.PI);
         if (this.flipped) {
            this.yRot += 180.0F;
         }
      }

      double m = Mth.wrapDegrees(this.yRot - this.yRotO);
      if (m < -170.0 || m >= 170.0) {
         this.yRot += 180.0F;
         this.flipped = !this.flipped;
      }

      this.setRot(this.yRot, this.xRot);
      if (this.getMinecartType() == AbstractMinecart.Type.RIDEABLE && getHorizontalDistanceSqr(this.getDeltaMovement()) > 0.01) {
         List<Entity> list = this.level.getEntities(this, this.getBoundingBox().inflate(0.2F, 0.0, 0.2F), EntitySelector.pushableBy(this));
         if (!list.isEmpty()) {
            for (int n = 0; n < list.size(); n++) {
               Entity lv3 = list.get(n);
               if (!(lv3 instanceof Player) && !(lv3 instanceof IronGolem) && !(lv3 instanceof AbstractMinecart) && !this.isVehicle() && !lv3.isPassenger()) {
                  lv3.startRiding(this);
               } else {
                  lv3.push(this);
               }
            }
         }
      } else {
         for (Entity lv4 : this.level.getEntities(this, this.getBoundingBox().inflate(0.2F, 0.0, 0.2F))) {
            if (!this.hasPassenger(lv4) && lv4.isPushable() && lv4 instanceof AbstractMinecart) {
               lv4.push(this);
            }
         }
      }

      this.updateInWaterStateAndDoFluidPushing();
      if (this.isInLava()) {
         this.lavaHurt();
         this.fallDistance *= 0.5F;
      }

      this.firstTick = false;
   }
}

travel.source:
public void travel(Vec3 arg) {
   if (this.isAlive()) {
      if (this.isVehicle() && this.canBeControlledByRider() && this.isSaddled()) {
         LivingEntity lv = (LivingEntity)this.getControllingPassenger();
         this.yRot = lv.yRot;
         this.yRotO = this.yRot;
         this.xRot = lv.xRot * 0.5F;
         this.setRot(this.yRot, this.xRot);
         this.yBodyRot = this.yRot;
         this.yHeadRot = this.yBodyRot;
         float f = lv.xxa * 0.5F;
         float g = lv.zza;
         if (g <= 0.0F) {
            g *= 0.25F;
            this.gallopSoundCounter = 0;
         }

         if (this.onGround && this.playerJumpPendingScale == 0.0F && this.isStanding() && !this.allowStandSliding) {
            f = 0.0F;
            g = 0.0F;
         }

         if (this.playerJumpPendingScale > 0.0F && !this.isJumping() && this.onGround) {
            double d = this.getCustomJump() * this.playerJumpPendingScale * this.getBlockJumpFactor();
            double e;
            if (this.hasEffect(MobEffects.JUMP)) {
               e = d + (this.getEffect(MobEffects.JUMP).getAmplifier() + 1) * 0.1F;
            } else {
               e = d;
            }

            Vec3 lv2 = this.getDeltaMovement();
            this.setDeltaMovement(lv2.x, e, lv2.z);
            this.setIsJumping(true);
            this.hasImpulse = true;
            if (g > 0.0F) {
               float h = Mth.sin(this.yRot * (float) (Math.PI / 180.0));
               float i = Mth.cos(this.yRot * (float) (Math.PI / 180.0));
               this.setDeltaMovement(this.getDeltaMovement().add(-0.4F * h * this.playerJumpPendingScale, 0.0, 0.4F * i * this.playerJumpPendingScale));
            }

            this.playerJumpPendingScale = 0.0F;
         }

         this.flyingSpeed = this.getSpeed() * 0.1F;
         if (this.isControlledByLocalInstance()) {
            this.setSpeed((float)this.getAttributeValue(Attributes.MOVEMENT_SPEED));
            super.travel(new Vec3(f, arg.y, g));
         } else if (lv instanceof Player) {
            this.setDeltaMovement(Vec3.ZERO);
         }

         if (this.onGround) {
            this.playerJumpPendingScale = 0.0F;
            this.setIsJumping(false);
         }

         this.calculateEntityAnimation(this, false);
      } else {
         this.flyingSpeed = 0.02F;
         super.travel(arg);
      }
   }
}

tick.source:
public void tick() {
   if (!this.leftOwner) {
      this.leftOwner = this.checkLeftOwner();
   }

   super.tick();
}

shoot.source:
public void shoot(double d, double e, double f, float g, float h) {
   Vec3 lv = new Vec3(d, e, f)
      .normalize()
      .add(this.random.nextGaussian() * 0.0075F * h, this.random.nextGaussian() * 0.0075F * h, this.random.nextGaussian() * 0.0075F * h)
      .scale(g);
   this.setDeltaMovement(lv);
   float i = Mth.sqrt(getHorizontalDistanceSqr(lv));
   this.yRot = (float)(Mth.atan2(lv.x, lv.z) * 180.0F / (float)Math.PI);
   this.xRot = (float)(Mth.atan2(lv.y, i) * 180.0F / (float)Math.PI);
   this.yRotO = this.yRot;
   this.xRotO = this.xRot;
}

shootFromRotation.source:
public void shootFromRotation(Entity arg, float f, float g, float h, float i, float j) {
   float k = -Mth.sin(g * (float) (Math.PI / 180.0)) * Mth.cos(f * (float) (Math.PI / 180.0));
   float l = -Mth.sin((f + h) * (float) (Math.PI / 180.0));
   float m = Mth.cos(g * (float) (Math.PI / 180.0)) * Mth.cos(f * (float) (Math.PI / 180.0));
   this.shoot(k, l, m, i, j);
   Vec3 lv = arg.getDeltaMovement();
   this.setDeltaMovement(this.getDeltaMovement().add(lv.x, arg.isOnGround() ? 0.0 : lv.y, lv.z));
}

checkLeftOwner.source:
private boolean checkLeftOwner() {
   Entity lv = this.getOwner();
   if (lv != null) {
      for (Entity lv2 : this.level
         .getEntities(this, this.getBoundingBox().expandTowards(this.getDeltaMovement()).inflate(1.0), arg -> !arg.isSpectator() && arg.isPickable())) {
         if (lv2.getRootVehicle() == lv.getRootVehicle()) {
            return false;
         }
      }
   }

   return true;
}

canHitEntity.source:
protected boolean canHitEntity(Entity arg) {
   if (!arg.isSpectator() && arg.isAlive() && arg.isPickable()) {
      Entity lv = this.getOwner();
      return lv == null || this.leftOwner || !lv.isPassengerOfSameVehicle(arg);
   } else {
      return false;
   }
}

onHit.source:
protected void onHit(HitResult arg) {
   HitResult.Type lv = arg.getType();
   if (lv == HitResult.Type.ENTITY) {
      this.onHitEntity((EntityHitResult)arg);
   } else if (lv == HitResult.Type.BLOCK) {
      this.onHitBlock((BlockHitResult)arg);
   }
}

onHitBlock.source:
protected void onHitBlock(BlockHitResult arg) {
   BlockHitResult lv = arg;
   BlockState lv2 = this.level.getBlockState(lv.getBlockPos());
   lv2.onProjectileHit(this.level, lv2, lv, this);
}

updateRotation.source:
protected void updateRotation() {
   Vec3 lv = this.getDeltaMovement();
   float f = Mth.sqrt(getHorizontalDistanceSqr(lv));
   this.xRot = lerpRotation(this.xRotO, (float)(Mth.atan2(lv.y, f) * 180.0F / (float)Math.PI));
