}

public static EntityHitResult getEntityHitResult(Level arg, Entity arg2, Vec3 arg3, Vec3 arg4, AABB arg5, Predicate<Entity> predicate, float f) {
   double d = Double.MAX_VALUE;
   Entity lv = null;

   for (Entity lv2 : arg.getEntities(arg2, arg5, predicate)) {
      AABB lv3 = lv2.getBoundingBox().inflate(f);
      Optional<Vec3> optional = lv3.clip(arg3, arg4);
      if (optional.isPresent()) {
         double e = arg3.distanceToSqr(optional.get());
         if (e < d) {
            lv = lv2;
            d = e;
         }
      }
   }

   return lv == null ? null : new EntityHitResult(lv);
}

rotateTowardsMovement.source:
public static void rotateTowardsMovement(Entity arg, float f) {
   Vec3 lv = arg.getDeltaMovement();
   if (lv.lengthSqr() != 0.0) {
      double d = lv.horizontalDistance();
      arg.setYRot((float)(Mth.atan2(lv.z, lv.x) * 180.0F / (float)Math.PI) + 90.0F);
      arg.setXRot((float)(Mth.atan2(d, lv.y) * 180.0F / (float)Math.PI) - 90.0F);

      while (arg.getXRot() - arg.xRotO < -180.0F) {
         arg.xRotO -= 360.0F;
      }

      while (arg.getXRot() - arg.xRotO >= 180.0F) {
         arg.xRotO += 360.0F;
      }

      while (arg.getYRot() - arg.yRotO < -180.0F) {
         arg.yRotO -= 360.0F;
      }

      while (arg.getYRot() - arg.yRotO >= 180.0F) {
         arg.yRotO += 360.0F;
      }

      arg.setXRot(Mth.lerp(f, arg.xRotO, arg.getXRot()));
      arg.setYRot(Mth.lerp(f, arg.yRotO, arg.getYRot()));
   }
}

