protected void onHitEntity(EntityHitResult arg) {
   super.onHitEntity(arg);
   Entity lv = arg.getEntity();
   float f = (float)this.getDeltaMovement().length();
   int i = Mth.ceil(Mth.clamp(f * this.baseDamage, 0.0, 2.147483647E9));
   if (this.getPierceLevel() > 0) {
      if (this.piercingIgnoreEntityIds == null) {
         this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
      }

      if (this.piercedAndKilledEntities == null) {
         this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
      }

      if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1) {
         this.discard();
         return;
      }

      this.piercingIgnoreEntityIds.add(lv.getId());
   }

   if (this.isCritArrow()) {
      long l = this.random.nextInt(i / 2 + 2);
      i = (int)Math.min(l + i, 2147483647L);
   }

   Entity lv2 = this.getOwner();
   DamageSource lv3;
   if (lv2 == null) {
      lv3 = DamageSource.arrow(this, this);
   } else {
      lv3 = DamageSource.arrow(this, lv2);
      if (lv2 instanceof LivingEntity) {
         ((LivingEntity)lv2).setLastHurtMob(lv);
      }
   }

   boolean bl = lv.getType() == EntityType.ENDERMAN;
   int j = lv.getRemainingFireTicks();
   if (this.isOnFire() && !bl) {
      lv.setSecondsOnFire(5);
   }

   if (lv.hurt(lv3, i)) {
      if (bl) {
         return;
      }

      if (lv instanceof LivingEntity lv4) {
         if (!this.level.isClientSide && this.getPierceLevel() <= 0) {
            lv4.setArrowCount(lv4.getArrowCount() + 1);
         }

         if (this.knockback > 0) {
            Vec3 lv5 = this.getDeltaMovement().multiply(1.0, 0.0, 1.0).normalize().scale(this.knockback * 0.6);
            if (lv5.lengthSqr() > 0.0) {
               lv4.push(lv5.x, 0.1, lv5.z);
            }
         }

         if (!this.level.isClientSide && lv2 instanceof LivingEntity) {
            EnchantmentHelper.doPostHurtEffects(lv4, lv2);
            EnchantmentHelper.doPostDamageEffects((LivingEntity)lv2, lv4);
         }

         this.doPostHurtEffects(lv4);
         if (lv2 != null && lv4 != lv2 && lv4 instanceof Player && lv2 instanceof ServerPlayer && !this.isSilent()) {
            ((ServerPlayer)lv2).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
         }

         if (!lv.isAlive() && this.piercedAndKilledEntities != null) {
            this.piercedAndKilledEntities.add(lv4);
         }

         if (!this.level.isClientSide && lv2 instanceof ServerPlayer lv6) {
            if (this.piercedAndKilledEntities != null && this.shotFromCrossbow()) {
               CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(lv6, this.piercedAndKilledEntities);
            } else if (!lv.isAlive() && this.shotFromCrossbow()) {
               CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(lv6, Arrays.asList(lv));
            }
         }
      }

      this.playSound(this.soundEvent, 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
      if (this.getPierceLevel() <= 0) {
         this.discard();
      }
   } else {
      lv.setRemainingFireTicks(j);
      this.setDeltaMovement(this.getDeltaMovement().scale(-0.1));
      this.setYRot(this.getYRot() + 180.0F);
      this.yRotO += 180.0F;
      if (!this.level.isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7) {
         if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
            this.spawnAtLocation(this.getPickupItem(), 0.1F);
         }

         this.discard();
      }
   }
}

