onHitEntity.source:
protected void onHitEntity(EntityHitResult arg) {
   Entity lv = arg.getEntity();
   float f = 8.0F;
   if (lv instanceof LivingEntity lv2) {
      f += EnchantmentHelper.getDamageBonus(this.tridentItem, lv2.getMobType());
   }

   Entity lv3 = this.getOwner();
   DamageSource lv4 = DamageSource.trident(this, lv3 == null ? this : lv3);
   this.dealtDamage = true;
   SoundEvent lv5 = SoundEvents.TRIDENT_HIT;
   if (lv.hurt(lv4, f)) {
      if (lv.getType() == EntityType.ENDERMAN) {
         return;
      }

      if (lv instanceof LivingEntity lv6) {
         if (lv3 instanceof LivingEntity) {
            EnchantmentHelper.doPostHurtEffects(lv6, lv3);
            EnchantmentHelper.doPostDamageEffects((LivingEntity)lv3, lv6);
         }

         this.doPostHurtEffects(lv6);
      }
   }

   this.setDeltaMovement(this.getDeltaMovement().multiply(-0.01, -0.1, -0.01));
   float g = 1.0F;
   if (this.level instanceof ServerLevel && this.level.isThundering() && this.isChanneling()) {
      BlockPos lv7 = lv.blockPosition();
      if (this.level.canSeeSky(lv7)) {
         LightningBolt lv8 = EntityType.LIGHTNING_BOLT.create(this.level);
         lv8.moveTo(Vec3.atBottomCenterOf(lv7));
         lv8.setCause(lv3 instanceof ServerPlayer ? (ServerPlayer)lv3 : null);
         this.level.addFreshEntity(lv8);
         lv5 = SoundEvents.TRIDENT_THUNDER;
         g = 5.0F;
      }
   }

   this.playSound(lv5, g, 1.0F);
}

tryPickup.source:
protected boolean tryPickup(Player arg) {
   return super.tryPickup(arg) || this.isNoPhysics() && this.ownedBy(arg) && arg.getInventory().add(this.getPickupItem());
}

tick.source:
public void tick() {
   Entity lv = this.getOwner();
   if (this.level.isClientSide || (lv == null || !lv.isRemoved()) && this.level.hasChunkAt(this.blockPosition())) {
      super.tick();
      if (this.shouldBurn()) {
         this.setSecondsOnFire(1);
      }

      HitResult lv2 = ProjectileUtil.getHitResult(this, this::canHitEntity);
      if (lv2.getType() != HitResult.Type.MISS) {
         this.onHit(lv2);
      }

      this.checkInsideBlocks();
      Vec3 lv3 = this.getDeltaMovement();
      double d = this.getX() + lv3.x;
      double e = this.getY() + lv3.y;
      double f = this.getZ() + lv3.z;
      ProjectileUtil.rotateTowardsMovement(this, 0.2F);
      float g = this.getInertia();
      if (this.isInWater()) {
         for (int i = 0; i < 4; i++) {
            float h = 0.25F;
            this.level.addParticle(ParticleTypes.BUBBLE, d - lv3.x * 0.25, e - lv3.y * 0.25, f - lv3.z * 0.25, lv3.x, lv3.y, lv3.z);
         }

         g = 0.8F;
      }

      this.setDeltaMovement(lv3.add(this.xPower, this.yPower, this.zPower).scale(g));
      this.level.addParticle(this.getTrailParticle(), d, e + 0.5, f, 0.0, 0.0, 0.0);
      this.setPos(d, e, f);
   } else {
      this.discard();
   }
}

canHitEntity.source:
protected boolean canHitEntity(Entity arg) {
   return super.canHitEntity(arg) && !arg.noPhysics;
}

tick.source:
public void tick() {
   super.tick();
   if (this.isAttachedToEntity()) {
      if (this.attachedToEntity == null) {
         this.entityData.get(DATA_ATTACHED_TO_TARGET).ifPresent(i -> {
            Entity lv = this.level.getEntity(i);
            if (lv instanceof LivingEntity) {
               this.attachedToEntity = (LivingEntity)lv;
            }
         });
      }

      if (this.attachedToEntity != null) {
         if (this.attachedToEntity.isFallFlying()) {
            Vec3 lv = this.attachedToEntity.getLookAngle();
            double d = 1.5;
            double e = 0.1;
            Vec3 lv2 = this.attachedToEntity.getDeltaMovement();
            this.attachedToEntity
               .setDeltaMovement(
                  lv2.add(lv.x * 0.1 + (lv.x * 1.5 - lv2.x) * 0.5, lv.y * 0.1 + (lv.y * 1.5 - lv2.y) * 0.5, lv.z * 0.1 + (lv.z * 1.5 - lv2.z) * 0.5)
               );
         }

         this.setPos(this.attachedToEntity.getX(), this.attachedToEntity.getY(), this.attachedToEntity.getZ());
         this.setDeltaMovement(this.attachedToEntity.getDeltaMovement());
      }
   } else {
      if (!this.isShotAtAngle()) {
         double f = this.horizontalCollision ? 1.0 : 1.15;
         this.setDeltaMovement(this.getDeltaMovement().multiply(f, 1.0, f).add(0.0, 0.04, 0.0));
      }

      Vec3 lv = this.getDeltaMovement();
      this.move(MoverType.SELF, lv);
      this.setDeltaMovement(lv);
   }

   HitResult lv3 = ProjectileUtil.getHitResult(this, this::canHitEntity);
   if (!this.noPhysics) {
      this.onHit(lv3);
      this.hasImpulse = true;
   }

   this.updateRotation();
   if (this.life == 0 && !this.isSilent()) {
      this.level.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.FIREWORK_ROCKET_LAUNCH, SoundSource.AMBIENT, 3.0F, 1.0F);
   }

   this.life++;
   if (this.level.isClientSide && this.life % 2 < 2) {
      this.level
         .addParticle(
            ParticleTypes.FIREWORK,
            this.getX(),
            this.getY() - 0.3,
            this.getZ(),
            this.random.nextGaussian() * 0.05,
            -this.getDeltaMovement().y * 0.5,
            this.random.nextGaussian() * 0.05
         );
   }

   if (!this.level.isClientSide && this.life > this.lifetime) {
      this.explode();
   }
}

explode.source:
private void explode() {
   this.level.broadcastEntityEvent(this, (byte)17);
   this.gameEvent(GameEvent.EXPLODE, this.getOwner());
   this.dealExplosionDamage();
   this.discard();
}

move.source:
public void move(MoverType arg, Vec3 arg2) {
   if (this.noPhysics) {
      this.setPos(this.getX() + arg2.x, this.getY() + arg2.y, this.getZ() + arg2.z);
   } else {
      this.wasOnFire = this.isOnFire();
      if (arg == MoverType.PISTON) {
         arg2 = this.limitPistonMovement(arg2);
         if (arg2.equals(Vec3.ZERO)) {
            return;
         }
      }

      this.level.getProfiler().push("move");
      if (this.stuckSpeedMultiplier.lengthSqr() > 1.0E-7) {
         arg2 = arg2.multiply(this.stuckSpeedMultiplier);
         this.stuckSpeedMultiplier = Vec3.ZERO;
         this.setDeltaMovement(Vec3.ZERO);
      }

      arg2 = this.maybeBackOffFromEdge(arg2, arg);
      Vec3 lv = this.collide(arg2);
      if (lv.lengthSqr() > 1.0E-7) {
         this.setPos(this.getX() + lv.x, this.getY() + lv.y, this.getZ() + lv.z);
      }

      this.level.getProfiler().pop();
      this.level.getProfiler().push("rest");
      this.horizontalCollision = !Mth.equal(arg2.x, lv.x) || !Mth.equal(arg2.z, lv.z);
      this.verticalCollision = arg2.y != lv.y;
      if (this.horizontalCollision) {
         this.minorHorizontalCollision = this.isHorizontalCollisionMinor(lv);
      } else {
         this.minorHorizontalCollision = false;
      }

      this.onGround = this.verticalCollision && arg2.y < 0.0;
      BlockPos lv2 = this.getOnPos();
      BlockState lv3 = this.level.getBlockState(lv2);
      this.checkFallDamage(lv.y, this.onGround, lv3, lv2);
      if (this.isRemoved()) {
         this.level.getProfiler().pop();
      } else {
         Vec3 lv4 = this.getDeltaMovement();
         if (arg2.x != lv.x) {
            this.setDeltaMovement(0.0, lv4.y, lv4.z);
         }

         if (arg2.z != lv.z) {
            this.setDeltaMovement(lv4.x, lv4.y, 0.0);
         }

         Block lv5 = lv3.getBlock();
         if (arg2.y != lv.y) {
            lv5.updateEntityAfterFallOn(this.level, this);
         }

         if (this.onGround && !this.isSteppingCarefully()) {
            lv5.stepOn(this.level, lv2, lv3, this);
         }

         Entity.MovementEmission lv6 = this.getMovementEmission();
         if (lv6.emitsAnything() && !this.isPassenger()) {
            double d = lv.x;
            double e = lv.y;
            double f = lv.z;
            this.flyDist = (float)(this.flyDist + lv.length() * 0.6);
            if (!lv3.is(BlockTags.CLIMBABLE) && !lv3.is(Blocks.POWDER_SNOW)) {
               e = 0.0;
            }

            this.walkDist = this.walkDist + (float)lv.horizontalDistance() * 0.6F;
            this.moveDist = this.moveDist + (float)Math.sqrt(d * d + e * e + f * f) * 0.6F;
            if (this.moveDist > this.nextStep && !lv3.isAir()) {
               this.nextStep = this.nextStep();
               if (this.isInWater()) {
                  if (lv6.emitsSounds()) {
                     Entity lv7 = this.isVehicle() && this.getControllingPassenger() != null ? this.getControllingPassenger() : this;
                     float g = lv7 == this ? 0.35F : 0.4F;
                     Vec3 lv8 = lv7.getDeltaMovement();
                     float h = Math.min(1.0F, (float)Math.sqrt(lv8.x * lv8.x * 0.2F + lv8.y * lv8.y + lv8.z * lv8.z * 0.2F) * g);
                     this.playSwimSound(h);
                  }

                  if (lv6.emitsEvents()) {
                     this.gameEvent(GameEvent.SWIM);
                  }
               } else {
                  if (lv6.emitsSounds()) {
                     this.playAmethystStepSound(lv3);
                     this.playStepSound(lv2, lv3);
                  }

                  if (lv6.emitsEvents() && !lv3.is(BlockTags.OCCLUDES_VIBRATION_SIGNALS)) {
                     this.gameEvent(GameEvent.STEP);
                  }
               }
            } else if (lv3.isAir()) {
               this.processFlappingMovement();
            }
         }

         this.tryCheckInsideBlocks();
         float i = this.getBlockSpeedFactor();
         this.setDeltaMovement(this.getDeltaMovement().multiply(i, 1.0, i));
         if (this.level.getBlockStatesIfLoaded(this.getBoundingBox().deflate(1.0E-6)).noneMatch(argx -> argx.is(BlockTags.FIRE) || argx.is(Blocks.LAVA))) {
            if (this.remainingFireTicks <= 0) {
               this.setRemainingFireTicks(-this.getFireImmuneTicks());
            }

            if (this.wasOnFire && (this.isInPowderSnow || this.isInWaterRainOrBubble())) {
               this.playEntityOnFireExtinguishedSound();
            }
         }

         if (this.isOnFire() && (this.isInPowderSnow || this.isInWaterRainOrBubble())) {
            this.setRemainingFireTicks(-this.getFireImmuneTicks());
         }

         this.level.getProfiler().pop();
      }
   }
}

collide.source:
private Vec3 collide(Vec3 arg) {
   AABB lv = this.getBoundingBox();
   List<VoxelShape> list = this.level.getEntityCollisions(this, lv.expandTowards(arg));
   Vec3 lv2 = arg.lengthSqr() == 0.0 ? arg : collideBoundingBox(this, arg, lv, this.level, list);
   boolean bl = arg.x != lv2.x;
   boolean bl2 = arg.y != lv2.y;
   boolean bl3 = arg.z != lv2.z;
   boolean bl4 = this.onGround || bl2 && arg.y < 0.0;
   if (this.maxUpStep > 0.0F && bl4 && (bl || bl3)) {
      Vec3 lv3 = collideBoundingBox(this, new Vec3(arg.x, this.maxUpStep, arg.z), lv, this.level, list);
      Vec3 lv4 = collideBoundingBox(this, new Vec3(0.0, this.maxUpStep, 0.0), lv.expandTowards(arg.x, 0.0, arg.z), this.level, list);
      if (lv4.y < this.maxUpStep) {
         Vec3 lv5 = collideBoundingBox(this, new Vec3(arg.x, 0.0, arg.z), lv.move(lv4), this.level, list).add(lv4);
         if (lv5.horizontalDistanceSqr() > lv3.horizontalDistanceSqr()) {
            lv3 = lv5;
         }
      }

      if (lv3.horizontalDistanceSqr() > lv2.horizontalDistanceSqr()) {
         return lv3.add(collideBoundingBox(this, new Vec3(0.0, -lv3.y + arg.y, 0.0), lv.move(lv3), this.level, list));
      }
   }

   return lv2;
}

push.source:
public void push(Entity arg) {
   if (!this.isPassengerOfSameVehicle(arg)) {
      if (!arg.noPhysics && !this.noPhysics) {
         double d = arg.getX() - this.getX();
         double e = arg.getZ() - this.getZ();
         double f = Mth.absMax(d, e);
         if (f >= 0.01F) {
            f = Math.sqrt(f);
            d /= f;
            e /= f;
            double g = 1.0 / f;
            if (g > 1.0) {
               g = 1.0;
            }

            d *= g;
            e *= g;
            d *= 0.05F;
            e *= 0.05F;
            if (!this.isVehicle()) {
               this.push(-d, 0.0, -e);
            }

            if (!arg.isVehicle()) {
               arg.push(d, 0.0, e);
            }
         }
      }
   }
}

public void push(double d, double e, double f) {
   this.setDeltaMovement(this.getDeltaMovement().add(d, e, f));
   this.hasImpulse = true;
}

rideTick.source:
public void rideTick() {
   this.setDeltaMovement(Vec3.ZERO);
   this.tick();
   if (this.isPassenger()) {
      this.getVehicle().positionRider(this);
   }
}

travel.source:
public void travel(Vec3 arg) {
   if (this.isEffectiveAi() || this.isControlledByLocalInstance()) {
      double d = 0.08;
      boolean bl = this.getDeltaMovement().y <= 0.0;
      if (bl && this.hasEffect(MobEffects.SLOW_FALLING)) {
         d = 0.01;
         this.resetFallDistance();
      }

      FluidState lv = this.level.getFluidState(this.blockPosition());
      if (this.isInWater() && this.isAffectedByFluids() && !this.canStandOnFluid(lv.getType())) {
         double e = this.getY();
         float f = this.isSprinting() ? 0.9F : this.getWaterSlowDown();
         float g = 0.02F;
         float h = EnchantmentHelper.getDepthStrider(this);
         if (h > 3.0F) {
            h = 3.0F;
         }

         if (!this.onGround) {
            h *= 0.5F;
         }

         if (h > 0.0F) {
            f += (0.54600006F - f) * h / 3.0F;
            g += (this.getSpeed() - g) * h / 3.0F;
         }

         if (this.hasEffect(MobEffects.DOLPHINS_GRACE)) {
            f = 0.96F;
         }

         this.moveRelative(g, arg);
         this.move(MoverType.SELF, this.getDeltaMovement());
         Vec3 lv2 = this.getDeltaMovement();
         if (this.horizontalCollision && this.onClimbable()) {
            lv2 = new Vec3(lv2.x, 0.2, lv2.z);
         }

         this.setDeltaMovement(lv2.multiply(f, 0.8F, f));
         Vec3 lv3 = this.getFluidFallingAdjustedMovement(d, bl, this.getDeltaMovement());
         this.setDeltaMovement(lv3);
         if (this.horizontalCollision && this.isFree(lv3.x, lv3.y + 0.6F - this.getY() + e, lv3.z)) {
            this.setDeltaMovement(lv3.x, 0.3F, lv3.z);
         }
      } else if (this.isInLava() && this.isAffectedByFluids() && !this.canStandOnFluid(lv.getType())) {
         double e = this.getY();
         this.moveRelative(0.02F, arg);
         this.move(MoverType.SELF, this.getDeltaMovement());
         if (this.getFluidHeight(FluidTags.LAVA) <= this.getFluidJumpThreshold()) {
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.5, 0.8F, 0.5));
            Vec3 lv4 = this.getFluidFallingAdjustedMovement(d, bl, this.getDeltaMovement());
            this.setDeltaMovement(lv4);
         } else {
            this.setDeltaMovement(this.getDeltaMovement().scale(0.5));
         }

         if (!this.isNoGravity()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0.0, -d / 4.0, 0.0));
         }

         Vec3 lv4 = this.getDeltaMovement();
         if (this.horizontalCollision && this.isFree(lv4.x, lv4.y + 0.6F - this.getY() + e, lv4.z)) {
            this.setDeltaMovement(lv4.x, 0.3F, lv4.z);
         }
      } else if (this.isFallFlying()) {
         Vec3 lv5 = this.getDeltaMovement();
         if (lv5.y > -0.5) {
            this.fallDistance = 1.0F;
         }

         Vec3 lv6 = this.getLookAngle();
         float f = this.getXRot() * (float) (Math.PI / 180.0);
         double i = Math.sqrt(lv6.x * lv6.x + lv6.z * lv6.z);
         double j = lv5.horizontalDistance();
         double k = lv6.length();
         float l = Mth.cos(f);
         l = (float)(l * (l * Math.min(1.0, k / 0.4)));
         lv5 = this.getDeltaMovement().add(0.0, d * (-1.0 + l * 0.75), 0.0);
         if (lv5.y < 0.0 && i > 0.0) {
            double m = lv5.y * -0.1 * l;
            lv5 = lv5.add(lv6.x * m / i, m, lv6.z * m / i);
         }

         if (f < 0.0F && i > 0.0) {
            double m = j * -Mth.sin(f) * 0.04;
            lv5 = lv5.add(-lv6.x * m / i, m * 3.2, -lv6.z * m / i);
         }

         if (i > 0.0) {
            lv5 = lv5.add((lv6.x / i * j - lv5.x) * 0.1, 0.0, (lv6.z / i * j - lv5.z) * 0.1);
         }

         this.setDeltaMovement(lv5.multiply(0.99F, 0.98F, 0.99F));
         this.move(MoverType.SELF, this.getDeltaMovement());
         if (this.horizontalCollision && !this.level.isClientSide) {
            double m = this.getDeltaMovement().horizontalDistance();
            double n = j - m;
            float o = (float)(n * 10.0 - 3.0);
            if (o > 0.0F) {
               this.playSound(this.getFallDamageSound((int)o), 1.0F, 1.0F);
               this.hurt(DamageSource.FLY_INTO_WALL, o);
            }
         }

         if (this.onGround && !this.level.isClientSide) {
            this.setSharedFlag(7, false);
         }
      } else {
         BlockPos lv7 = this.getBlockPosBelowThatAffectsMyMovement();
         float p = this.level.getBlockState(lv7).getBlock().getFriction();
         float f = this.onGround ? p * 0.91F : 0.91F;
         Vec3 lv8 = this.handleRelativeFrictionAndCalculateMovement(arg, p);
         double q = lv8.y;
         if (this.hasEffect(MobEffects.LEVITATION)) {
            q += (0.05 * (this.getEffect(MobEffects.LEVITATION).getAmplifier() + 1) - lv8.y) * 0.2;
            this.resetFallDistance();
         } else if (this.level.isClientSide && !this.level.hasChunkAt(lv7)) {
            if (this.getY() > this.level.getMinBuildHeight()) {
               q = -0.1;
            } else {
               q = 0.0;
            }
         } else if (!this.isNoGravity()) {
            q -= d;
         }

         if (this.shouldDiscardFriction()) {
            this.setDeltaMovement(lv8.x, q, lv8.z);
         } else {
            this.setDeltaMovement(lv8.x * f, q * 0.98F, lv8.z * f);
         }
      }
   }

   this.calculateEntityAnimation(this, this instanceof FlyingAnimal);
}

handleRelativeFrictionAndCalculateMoveme.source:
public Vec3 handleRelativeFrictionAndCalculateMovement(Vec3 arg, float f) {
   this.moveRelative(this.getFrictionInfluencedSpeed(f), arg);
   this.setDeltaMovement(this.handleOnClimbable(this.getDeltaMovement()));
   this.move(MoverType.SELF, this.getDeltaMovement());
   Vec3 lv = this.getDeltaMovement();
   if ((this.horizontalCollision || this.jumping)
      && (this.onClimbable() || this.getFeetBlockState().is(Blocks.POWDER_SNOW) && PowderSnowBlock.canEntityWalkOnPowderSnow(this))) {
      lv = new Vec3(lv.x, 0.2, lv.z);
   }

   return lv;
}

causeFallDamage.source:
public boolean causeFallDamage(float f, float g, DamageSource arg) {
   boolean bl = super.causeFallDamage(f, g, arg);
   int i = this.calculateFallDamage(f, g);
   if (i > 0) {
      this.playSound(this.getFallDamageSound(i), 1.0F, 1.0F);
      this.playBlockFallSound();
      this.hurt(arg, i);
      return true;
   } else {
      return bl;
   }
}

travel.source:
public void travel(Vec3 arg) {
   double d = this.getX();
   double e = this.getY();
   double f = this.getZ();
   if (this.isSwimming() && !this.isPassenger()) {
      double g = this.getLookAngle().y;
      double h = g < -0.2 ? 0.085 : 0.06;
      if (g <= 0.0 || this.jumping || !this.level.getBlockState(new BlockPos(this.getX(), this.getY() + 1.0 - 0.1, this.getZ())).getFluidState().isEmpty()) {
         Vec3 lv = this.getDeltaMovement();
         this.setDeltaMovement(lv.add(0.0, (g - lv.y) * h, 0.0));
      }
   }

   if (this.abilities.flying && !this.isPassenger()) {
      double g = this.getDeltaMovement().y;
      float i = this.flyingSpeed;
      this.flyingSpeed = this.abilities.getFlyingSpeed() * (this.isSprinting() ? 2 : 1);
      super.travel(arg);
      Vec3 lv2 = this.getDeltaMovement();
      this.setDeltaMovement(lv2.x, g * 0.6, lv2.z);
      this.flyingSpeed = i;
      this.resetFallDistance();
      this.setSharedFlag(7, false);
   } else {
      super.travel(arg);
   }

   this.checkMovementStatistics(this.getX() - d, this.getY() - e, this.getZ() - f);
}

aiStep.source:
public void aiStep() {
   if (this.jumpTriggerTime > 0) {
      this.jumpTriggerTime--;
   }

   if (this.level.getDifficulty() == Difficulty.PEACEFUL && this.level.getGameRules().getBoolean(GameRules.RULE_NATURAL_REGENERATION)) {
      if (this.getHealth() < this.getMaxHealth() && this.tickCount % 20 == 0) {
         this.heal(1.0F);
      }

      if (this.foodData.needsFood() && this.tickCount % 10 == 0) {
         this.foodData.setFoodLevel(this.foodData.getFoodLevel() + 1);
      }
   }

   this.inventory.tick();
   this.oBob = this.bob;
   super.aiStep();
   this.flyingSpeed = 0.02F;
   if (this.isSprinting()) {
      this.flyingSpeed = (float)(this.flyingSpeed + 0.005999999865889549);
   }

   this.setSpeed((float)this.getAttributeValue(Attributes.MOVEMENT_SPEED));
   float f;
   if (this.onGround && !this.isDeadOrDying() && !this.isSwimming()) {
      f = Math.min(0.1F, (float)this.getDeltaMovement().horizontalDistance());
   } else {
      f = 0.0F;
   }

   this.bob = this.bob + (f - this.bob) * 0.4F;
   if (this.getHealth() > 0.0F && !this.isSpectator()) {
      AABB lv;
      if (this.isPassenger() && !this.getVehicle().isRemoved()) {
         lv = this.getBoundingBox().minmax(this.getVehicle().getBoundingBox()).inflate(1.0, 0.0, 1.0);
      } else {
         lv = this.getBoundingBox().inflate(1.0, 0.5, 1.0);
      }

      List<Entity> list = this.level.getEntities(this, lv);
      List<Entity> list2 = Lists.newArrayList();

      for (int i = 0; i < list.size(); i++) {
         Entity lv2 = list.get(i);
         if (lv2.getType() == EntityType.EXPERIENCE_ORB) {
            list2.add(lv2);
         } else if (!lv2.isRemoved()) {
            this.touch(lv2);
         }
      }

      if (!list2.isEmpty()) {
         this.touch(Util.getRandom(list2, this.random));
      }
   }

   this.playShoulderEntityAmbientSound(this.getShoulderEntityLeft());
   this.playShoulderEntityAmbientSound(this.getShoulderEntityRight());
   if (!this.level.isClientSide && (this.fallDistance > 0.5F || this.isInWater()) || this.abilities.flying || this.isSleeping() || this.isInPowderSnow) {
      this.removeEntitiesOnShoulder();
   }
}

