getHitResult.source:
public static HitResult getHitResult(Entity arg, Predicate<Entity> predicate) {
   Vec3 lv = arg.getDeltaMovement();
   Level lv2 = arg.level;
   Vec3 lv3 = arg.position();
   Vec3 lv4 = lv3.add(lv);
   HitResult lv5 = lv2.clip(new ClipContext(lv3, lv4, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, arg));
   if (lv5.getType() != HitResult.Type.MISS) {
      lv4 = lv5.getLocation();
   }

   HitResult lv6 = getEntityHitResult(lv2, arg, lv3, lv4, arg.getBoundingBox().expandTowards(arg.getDeltaMovement()).inflate(1.0), predicate);
   if (lv6 != null) {
      lv5 = lv6;
   }

   return lv5;
}

getEntityHitResult.source:
public static EntityHitResult getEntityHitResult(Entity arg, Vec3 arg2, Vec3 arg3, AABB arg4, Predicate<Entity> predicate, double d) {
   Level lv = arg.level;
   double e = d;
   Entity lv2 = null;
   Vec3 lv3 = null;

   for (Entity lv4 : lv.getEntities(arg, arg4, predicate)) {
      AABB lv5 = lv4.getBoundingBox().inflate(lv4.getPickRadius());
      Optional<Vec3> optional = lv5.clip(arg2, arg3);
      if (lv5.contains(arg2)) {
         if (e >= 0.0) {
            lv2 = lv4;
            lv3 = optional.orElse(arg2);
            e = 0.0;
         }
      } else if (optional.isPresent()) {
         Vec3 lv6 = optional.get();
         double f = arg2.distanceToSqr(lv6);
         if (f < e || e == 0.0) {
            if (lv4.getRootVehicle() == arg.getRootVehicle()) {
               if (e == 0.0) {
                  lv2 = lv4;
                  lv3 = lv6;
               }
            } else {
               lv2 = lv4;
               lv3 = lv6;
               e = f;
            }
         }
      }
   }

   return lv2 == null ? null : new EntityHitResult(lv2, lv3);
}

public static EntityHitResult getEntityHitResult(Level arg, Entity arg2, Vec3 arg3, Vec3 arg4, AABB arg5, Predicate<Entity> predicate) {
   return getEntityHitResult(arg, arg2, arg3, arg4, arg5, predicate, 0.3F);
}

public static EntityHitResult getEntityHitResult(Level arg, Entity arg2, Vec3 arg3, Vec3 arg4, AABB arg5, Predicate<Entity> predicate, float f) {
   double d = Double.MAX_VALUE;
   Entity lv = null;

   for (Entity lv2 : arg.getEntities(arg2, arg5, predicate)) {
      AABB lv3 = lv2.getBoundingBox().inflate(f);
      Optional<Vec3> optional = lv3.clip(arg3, arg4);
      if (optional.isPresent()) {
         double e = arg3.distanceToSqr(optional.get());
         if (e < d) {
            lv = lv2;
            d = e;
         }
      }
   }

   return lv == null ? null : new EntityHitResult(lv);
}

rotateTowardsMovement.source:
public static void rotateTowardsMovement(Entity arg, float f) {
   Vec3 lv = arg.getDeltaMovement();
   if (lv.lengthSqr() != 0.0) {
      double d = lv.horizontalDistance();
      arg.setYRot((float)(Mth.atan2(lv.z, lv.x) * 180.0F / (float)Math.PI) + 90.0F);
      arg.setXRot((float)(Mth.atan2(d, lv.y) * 180.0F / (float)Math.PI) - 90.0F);

      while (arg.getXRot() - arg.xRotO < -180.0F) {
         arg.xRotO -= 360.0F;
      }

      while (arg.getXRot() - arg.xRotO >= 180.0F) {
         arg.xRotO += 360.0F;
      }

      while (arg.getYRot() - arg.yRotO < -180.0F) {
         arg.yRotO -= 360.0F;
      }

      while (arg.getYRot() - arg.yRotO >= 180.0F) {
         arg.yRotO += 360.0F;
      }

      arg.setXRot(Mth.lerp(f, arg.xRotO, arg.getXRot()));
      arg.setYRot(Mth.lerp(f, arg.yRotO, arg.getYRot()));
   }
}

tick.source:
public void tick() {
   super.tick();
   HitResult lv = ProjectileUtil.getHitResult(this, this::canHitEntity);
   boolean bl = false;
   if (lv.getType() == HitResult.Type.BLOCK) {
      BlockPos lv2 = ((BlockHitResult)lv).getBlockPos();
      BlockState lv3 = this.level.getBlockState(lv2);
      if (lv3.is(Blocks.NETHER_PORTAL)) {
         this.handleInsidePortal(lv2);
         bl = true;
      } else if (lv3.is(Blocks.END_GATEWAY)) {
         BlockEntity lv4 = this.level.getBlockEntity(lv2);
         if (lv4 instanceof TheEndGatewayBlockEntity && TheEndGatewayBlockEntity.canEntityTeleport(this)) {
            TheEndGatewayBlockEntity.teleportEntity(this.level, lv2, lv3, this, (TheEndGatewayBlockEntity)lv4);
         }

         bl = true;
      }
   }

   if (lv.getType() != HitResult.Type.MISS && !bl) {
      this.onHit(lv);
   }

   this.checkInsideBlocks();
   Vec3 lv5 = this.getDeltaMovement();
   double d = this.getX() + lv5.x;
   double e = this.getY() + lv5.y;
   double f = this.getZ() + lv5.z;
   this.updateRotation();
   float h;
   if (this.isInWater()) {
      for (int i = 0; i < 4; i++) {
         float g = 0.25F;
         this.level.addParticle(ParticleTypes.BUBBLE, d - lv5.x * 0.25, e - lv5.y * 0.25, f - lv5.z * 0.25, lv5.x, lv5.y, lv5.z);
      }

      h = 0.8F;
   } else {
      h = 0.99F;
   }

   this.setDeltaMovement(lv5.scale(h));
   if (!this.isNoGravity()) {
      Vec3 lv6 = this.getDeltaMovement();
      this.setDeltaMovement(lv6.x, lv6.y - this.getGravity(), lv6.z);
   }

   this.setPos(d, e, f);
}

public void tick() {
   super.tick();
   boolean bl = this.isNoPhysics();
   Vec3 lv = this.getDeltaMovement();
   if (this.xRotO == 0.0F && this.yRotO == 0.0F) {
      double d = lv.horizontalDistance();
      this.setYRot((float)(Mth.atan2(lv.x, lv.z) * 180.0F / (float)Math.PI));
      this.setXRot((float)(Mth.atan2(lv.y, d) * 180.0F / (float)Math.PI));
      this.yRotO = this.getYRot();
      this.xRotO = this.getXRot();
   }

   BlockPos lv2 = this.blockPosition();
   BlockState lv3 = this.level.getBlockState(lv2);
   if (!lv3.isAir() && !bl) {
      VoxelShape lv4 = lv3.getCollisionShape(this.level, lv2);
      if (!lv4.isEmpty()) {
         Vec3 lv5 = this.position();

         for (AABB lv6 : lv4.toAabbs()) {
            if (lv6.move(lv2).contains(lv5)) {
               this.inGround = true;
               break;
            }
         }
      }
   }

   if (this.shakeTime > 0) {
      this.shakeTime--;
   }

   if (this.isInWaterOrRain() || lv3.is(Blocks.POWDER_SNOW)) {
      this.clearFire();
   }

   if (this.inGround && !bl) {
      if (this.lastState != lv3 && this.shouldFall()) {
         this.startFalling();
      } else if (!this.level.isClientSide) {
         this.tickDespawn();
      }

      this.inGroundTime++;
   } else {
      this.inGroundTime = 0;
      Vec3 lv7 = this.position();
      Vec3 lv5 = lv7.add(lv);
      HitResult lv8 = this.level.clip(new ClipContext(lv7, lv5, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
      if (lv8.getType() != HitResult.Type.MISS) {
         lv5 = lv8.getLocation();
      }

      while (!this.isRemoved()) {
         EntityHitResult lv9 = this.findHitEntity(lv7, lv5);
         if (lv9 != null) {
            lv8 = lv9;
         }

         if (lv8 != null && lv8.getType() == HitResult.Type.ENTITY) {
            Entity lv10 = ((EntityHitResult)lv8).getEntity();
            Entity lv11 = this.getOwner();
            if (lv10 instanceof Player && lv11 instanceof Player && !((Player)lv11).canHarmPlayer((Player)lv10)) {
               lv8 = null;
               lv9 = null;
            }
         }

         if (lv8 != null && !bl) {
            this.onHit(lv8);
            this.hasImpulse = true;
         }

         if (lv9 == null || this.getPierceLevel() <= 0) {
            break;
         }

         lv8 = null;
      }

      lv = this.getDeltaMovement();
      double e = lv.x;
      double f = lv.y;
      double g = lv.z;
      if (this.isCritArrow()) {
         for (int i = 0; i < 4; i++) {
            this.level.addParticle(ParticleTypes.CRIT, this.getX() + e * i / 4.0, this.getY() + f * i / 4.0, this.getZ() + g * i / 4.0, -e, -f + 0.2, -g);
         }
      }

      double h = this.getX() + e;
      double j = this.getY() + f;
      double k = this.getZ() + g;
      double l = lv.horizontalDistance();
      if (bl) {
         this.setYRot((float)(Mth.atan2(-e, -g) * 180.0F / (float)Math.PI));
      } else {
         this.setYRot((float)(Mth.atan2(e, g) * 180.0F / (float)Math.PI));
      }

      this.setXRot((float)(Mth.atan2(f, l) * 180.0F / (float)Math.PI));
      this.setXRot(lerpRotation(this.xRotO, this.getXRot()));
      this.setYRot(lerpRotation(this.yRotO, this.getYRot()));
      float m = 0.99F;
      float n = 0.05F;
      if (this.isInWater()) {
         for (int o = 0; o < 4; o++) {
            float p = 0.25F;
            this.level.addParticle(ParticleTypes.BUBBLE, h - e * 0.25, j - f * 0.25, k - g * 0.25, e, f, g);
         }

         m = this.getWaterInertia();
      }

      this.setDeltaMovement(lv.scale(m));
      if (!this.isNoGravity() && !bl) {
         Vec3 lv12 = this.getDeltaMovement();
         this.setDeltaMovement(lv12.x, lv12.y - 0.05F, lv12.z);
      }

      this.setPos(h, j, k);
      this.checkInsideBlocks();
   }
}

