      }

      this.onGround = this.verticalCollision && arg2.y < 0.0;
      BlockPos lv3 = this.getOnPosLegacy();
      BlockState lv4 = this.level.getBlockState(lv3);
      this.checkFallDamage(lv.y, this.onGround, lv4, lv3);
