         this.level.getProfiler().pop();
      } else {
         if (this.horizontalCollision) {
            Vec3 lv5 = this.getDeltaMovement();
            this.setDeltaMovement(bl ? 0.0 : lv5.x, lv5.y, bl2 ? 0.0 : lv5.z);
         }

         Block lv6 = lv4.getBlock();
         if (arg2.y != lv.y) {
