            double f = lv.y;
            double g = lv.z;
            this.flyDist = this.flyDist + (float)(lv.length() * 0.6);
            boolean bl3 = lv4.is(BlockTags.CLIMBABLE) || lv4.is(Blocks.POWDER_SNOW);
            if (!bl3) {
               f = 0.0;
            }

            this.walkDist = this.walkDist + (float)lv.horizontalDistance() * 0.6F;
            this.moveDist = this.moveDist + (float)Math.sqrt(e * e + f * f + g * g) * 0.6F;
            if (this.moveDist > this.nextStep && !lv4.isAir()) {
               this.nextStep = this.nextStep();
               if (this.isInWater()) {
                  if (lv7.emitsSounds()) {
                     Entity lv8 = this.isVehicle() && this.getControllingPassenger() != null ? this.getControllingPassenger() : this;
                     float h = lv8 == this ? 0.35F : 0.4F;
                     Vec3 lv9 = lv8.getDeltaMovement();
                     float i = Math.min(1.0F, (float)Math.sqrt(lv9.x * lv9.x * 0.2F + lv9.y * lv9.y + lv9.z * lv9.z * 0.2F) * h);
                     this.playSwimSound(i);
