         double e = arg.getZ() - this.getZ();
         double f = Mth.absMax(d, e);
         if (f >= 0.01F) {
            f = Math.sqrt(f);
            d /= f;
            e /= f;
            double g = 1.0 / f;
            if (g > 1.0) {
               g = 1.0;
            }

            d *= g;
            e *= g;
            d *= 0.05F;
            e *= 0.05F;
            if (!this.isVehicle() && this.isPushable()) {
               this.push(-d, 0.0, -e);
            }

            if (!arg.isVehicle() && arg.isPushable()) {
               arg.push(d, 0.0, e);
            }
         }
      }
   }
}

