updateRotation.source:
protected void updateRotation() {
   Vec3 movement = this.getDeltaMovement();
   double sd = movement.horizontalDistance();
   this.setXRot(lerpRotation(this.xRotO, (float)(Mth.atan2(movement.y, sd) * 180.0F / (float)Math.PI)));
   this.setYRot(lerpRotation(this.yRotO, (float)(Mth.atan2(movement.x, movement.z) * 180.0F / (float)Math.PI)));
}

getHitResult.source:
private static HitResult getHitResult(
   final Vec3 from,
   final Entity source,
   final Predicate<Entity> matching,
   final Vec3 delta,
   final Level level,
   final float entityMargin,
   final ClipContext.Block clipType
) {
   Vec3 to = from.add(delta);
   HitResult hitResult = level.clipIncludingBorder(new ClipContext(from, to, clipType, ClipContext.Fluid.NONE, source));
   if (hitResult.getType() != HitResult.Type.MISS) {
      to = hitResult.getLocation();
   }

   HitResult entityHit = getEntityHitResult(level, source, from, to, source.getBoundingBox().expandTowards(delta).inflate(1.0), matching, entityMargin);
   if (entityHit != null) {
      hitResult = entityHit;
   }

   return hitResult;
}

getHitResultOnMoveVector.source:
public static HitResult getHitResultOnMoveVector(final Entity source, final Predicate<Entity> matching) {
   Vec3 movement = source.getDeltaMovement();
   Level level = source.level();
   Vec3 from = source.position();
   return getHitResult(from, source, matching, movement, level, computeMargin(source), ClipContext.Block.COLLIDER);
}

public static HitResult getHitResultOnMoveVector(final Entity source, final Predicate<Entity> matching, final ClipContext.Block clipType) {
   Vec3 movement = source.getDeltaMovement();
   Level level = source.level();
   Vec3 from = source.position();
   return getHitResult(from, source, matching, movement, level, computeMargin(source), clipType);
}

getEntityHitResult.source:
public static @Nullable EntityHitResult getEntityHitResult(
   final Entity except, final Vec3 from, final Vec3 to, final AABB box, final Predicate<Entity> matching, final double maxValue
) {
   Level level = except.level();
   double nearest = maxValue;
   Entity hovered = null;
   Vec3 hoveredPos = null;

   for (Entity entity : level.getEntities(except, box, matching)) {
      AABB bb = entity.getBoundingBox().inflate(entity.getPickRadius());
      Optional<Vec3> clipPoint = bb.clip(from, to);
      if (bb.contains(from)) {
         if (nearest >= 0.0) {
            hovered = entity;
            hoveredPos = clipPoint.orElse(from);
            nearest = 0.0;
         }
      } else if (clipPoint.isPresent()) {
         Vec3 location = clipPoint.get();
         double dd = from.distanceToSqr(location);
         if (dd < nearest || nearest == 0.0) {
            if (entity.getRootVehicle() == except.getRootVehicle()) {
               if (nearest == 0.0) {
                  hovered = entity;
                  hoveredPos = location;
               }
            } else {
               hovered = entity;
               hoveredPos = location;
               nearest = dd;
            }
         }
      }
   }

   return hovered == null ? null : new EntityHitResult(hovered, hoveredPos);
}

public static @Nullable EntityHitResult getEntityHitResult(
   final Level level, final Projectile source, final Vec3 from, final Vec3 to, final AABB targetSearchArea, final Predicate<Entity> matching
) {
   return getEntityHitResult(level, source, from, to, targetSearchArea, matching, computeMargin(source));
}

public static @Nullable EntityHitResult getEntityHitResult(
   final Level level,
   final Entity source,
   final Vec3 from,
   final Vec3 to,
   final AABB targetSearchArea,
   final Predicate<Entity> matching,
   final float entityMargin
) {
   double nearest = Double.MAX_VALUE;
   Optional<Vec3> nearestLocation = Optional.empty();
   Entity hitEntity = null;

   for (Entity entity : level.getEntities(source, targetSearchArea, matching)) {
      AABB bb = entity.getBoundingBox().inflate(entityMargin);
      Optional<Vec3> location = bb.clip(from, to);
      if (location.isPresent()) {
         double dd = from.distanceToSqr(location.get());
         if (dd < nearest) {
            hitEntity = entity;
            nearest = dd;
            nearestLocation = location;
         }
      }
   }

   return hitEntity == null ? null : new EntityHitResult(hitEntity, nearestLocation.get());
}

rotateTowardsMovement.source:
public static void rotateTowardsMovement(final Entity projectile, final float rotationSpeed) {
   Vec3 movement = projectile.getDeltaMovement();
   if (movement.lengthSqr() != 0.0) {
      double sd = movement.horizontalDistance();
      projectile.setYRot((float)(Mth.atan2(movement.z, movement.x) * 180.0F / (float)Math.PI) + 90.0F);
      projectile.setXRot((float)(Mth.atan2(sd, movement.y) * 180.0F / (float)Math.PI) - 90.0F);

      while (projectile.getXRot() - projectile.xRotO < -180.0F) {
         projectile.xRotO -= 360.0F;
      }

      while (projectile.getXRot() - projectile.xRotO >= 180.0F) {
         projectile.xRotO += 360.0F;
      }

      while (projectile.getYRot() - projectile.yRotO < -180.0F) {
         projectile.yRotO -= 360.0F;
      }

      while (projectile.getYRot() - projectile.yRotO >= 180.0F) {
         projectile.yRotO += 360.0F;
      }

      projectile.setXRot(Mth.lerp(rotationSpeed, projectile.xRotO, projectile.getXRot()));
      projectile.setYRot(Mth.lerp(rotationSpeed, projectile.yRotO, projectile.getYRot()));
   }
}

tick.source:
public void tick() {
   this.handleFirstTickBubbleColumn();
   this.applyGravity();
   this.applyInertia();
   HitResult result = ProjectileUtil.getHitResultOnMoveVector(this, this::canHitEntity);
   Vec3 newPosition;
   if (result.getType() != HitResult.Type.MISS) {
      newPosition = result.getLocation();
   } else {
      newPosition = this.position().add(this.getDeltaMovement());
   }

   this.setPos(newPosition);
   this.updateRotation();
   this.applyEffectsFromBlocks();
   super.tick();
   if (result.getType() != HitResult.Type.MISS && this.isAlive()) {
      this.hitTargetOrDeflectSelf(result);
   }
}

applyInertia.source:
private void applyInertia() {
   Vec3 movement = this.getDeltaMovement();
   Vec3 position = this.position();
   float inertia;
   if (this.isInWater()) {
      for (int i = 0; i < 4; i++) {
         float s = 0.25F;
         this.level()
            .addParticle(
               ParticleTypes.BUBBLE,
               position.x - movement.x * 0.25,
               position.y - movement.y * 0.25,
               position.z - movement.z * 0.25,
               movement.x,
               movement.y,
               movement.z
            );
      }

      inertia = 0.8F;
   } else {
      inertia = 0.99F;
   }

   this.setDeltaMovement(movement.scale(inertia));
}

handleFirstTickBubbleColumn.source:
private void handleFirstTickBubbleColumn() {
   if (this.firstTick) {
      for (BlockPos pos : BlockPos.betweenClosed(this.getBoundingBox())) {
         BlockState state = this.level().getBlockState(pos);
         if (state.is(Blocks.BUBBLE_COLUMN)) {
            state.entityInside(this.level(), pos, this, InsideBlockEffectApplier.NOOP, true);
         }
      }
   }
}

tick.source:
public void tick() {
   boolean physicsEnabled = !this.isNoPhysics();
   Vec3 movement = this.getDeltaMovement();
   BlockPos blockPos = this.blockPosition();
   BlockState blockState = this.level().getBlockState(blockPos);
   if (!blockState.isAir() && physicsEnabled) {
      VoxelShape shape = blockState.getCollisionShape(this.level(), blockPos);
      if (!shape.isEmpty()) {
         Vec3 position = this.position();

         for (AABB aabb : shape.toAabbs()) {
            if (aabb.move(blockPos).contains(position)) {
               this.setDeltaMovement(Vec3.ZERO);
               this.setInGround(true);
               break;
            }
         }
      }
   }

   if (this.shakeTime > 0) {
      this.shakeTime--;
   }

   if (this.isInWaterOrRain()) {
      this.clearFire();
   }

   if (this.isInGround() && physicsEnabled) {
      if (!this.level().isClientSide()) {
         if (this.lastState != blockState && this.shouldFall()) {
            this.startFalling();
         } else {
            this.tickDespawn();
         }
      }

      this.inGroundTime++;
      if (this.isAlive()) {
         this.applyEffectsFromBlocks();
      }

      if (!this.level().isClientSide()) {
         this.setSharedFlagOnFire(this.getRemainingFireTicks() > 0);
      }
   } else {
      this.inGroundTime = 0;
      Vec3 originalPosition = this.position();
      if (this.isInWater()) {
         this.applyInertia(this.getWaterInertia());
         this.addBubbleParticles(originalPosition);
      }

      if (this.isCritArrow()) {
         for (int i = 0; i < 4; i++) {
            this.level()
               .addParticle(
                  ParticleTypes.CRIT,
                  originalPosition.x + movement.x * i / 4.0,
                  originalPosition.y + movement.y * i / 4.0,
                  originalPosition.z + movement.z * i / 4.0,
                  -movement.x,
                  -movement.y + 0.2,
                  -movement.z
               );
         }
      }

      float yRot;
      if (!physicsEnabled) {
         yRot = (float)(Mth.atan2(-movement.x, -movement.z) * 180.0F / (float)Math.PI);
      } else {
         yRot = (float)(Mth.atan2(movement.x, movement.z) * 180.0F / (float)Math.PI);
      }

      float xRot = (float)(Mth.atan2(movement.y, movement.horizontalDistance()) * 180.0F / (float)Math.PI);
      this.setXRot(lerpRotation(this.getXRot(), xRot));
      this.setYRot(lerpRotation(this.getYRot(), yRot));
      this.checkLeftOwner();
      if (physicsEnabled) {
         BlockHitResult blockHitResult = this.level()
            .clipIncludingBorder(new ClipContext(originalPosition, originalPosition.add(movement), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
         this.stepMoveAndHit(blockHitResult);
      } else {
         this.setPos(originalPosition.add(movement));
         this.applyEffectsFromBlocks();
      }

      if (!this.isInWater()) {
         this.applyInertia(0.99F);
      }

      if (physicsEnabled && !this.isInGround()) {
         this.applyGravity();
      }

      super.tick();
   }
}

